        content = content[3:]
    if content.endswith('```'):
        content = content[:-3]
    content = content.strip()
    try:
        data = json.loads(content)
    except json.JSONDecodeError:
        start = content.find('{')
        end = content.rfind('}')
        if start != -1 and end != -1:
            try:
                data = json.loads(content[start:end + 1])
            except json.JSONDecodeError:
                return None
        else:
            return None
    if not isinstance(data, dict):
        return None
    return _normalize_json_schema(data)


# Patterns that indicate a line is contact info, not a professional summary
_CONTACT_PATTERNS = re.compile(
    r'(\b\d{3}[-.]?\d{3}[-.]?\d{4}\b'        # phone numbers
    r'|@\w+\.\w+'                              # email addresses
    r'|github\.com/'                           # GitHub URLs
    r'|linkedin\.com/'                         # LinkedIn URLs
    r'|^\s*\d+\s+[\w\s]+,\s*\w+\s*$'          # "123 Main St, City"
    r')',
    re.IGNORECASE,
)

# Bullets that are too short or generic to be useful
_PLACEHOLDER_PATTERNS = re.compile(
    r'^(worked as|provided|supported|responsible for|duties included|helped with)\s',
    re.IGNORECASE,
)

MAX_BULLETS_PER_ROLE = 5
MAX_ACHIEVEMENTS = 4
MAX_PROJECTS = 4
MIN_BULLET_LENGTH = 25


def _is_contact_info(text: str) -> bool:
    """Return True if text looks like contact information rather than a summary."""
    if not text or not text.strip():
        return True
    return bool(_CONTACT_PATTERNS.search(text))


def _is_placeholder_bullet(text: str) -> bool:
    """Return True if a bullet is too generic/placeholder-like."""
    stripped = text.strip()
    if len(stripped) < MIN_BULLET_LENGTH:
        return True
    if _PLACEHOLDER_PATTERNS.match(stripped):
        return True
    return False


def _normalize_json_schema(data: dict) -> dict:
    """Normalize a parsed JSON dict to the canonical schema.

    The Copilot proxy sometimes returns alternative key names:
      - ``experience`` instead of ``experience_bullets_by_role``
      - ``highlights`` instead of ``bullets``
      - ``job_title`` instead of ``role``
      - ``skills`` as a flat list instead of a dict

    This function converts all known alternatives to the canonical keys so
    downstream code doesn't need to handle multiple schemas.
    """
    # Normalize experience: list of {job_title, highlights} -> experience_bullets_by_role
    if 'experience_bullets_by_role' not in data and 'experience' in data:
        raw_exp = data.get('experience', [])
        if isinstance(raw_exp, list):
            normalized = []
            for entry in raw_exp:
                if not isinstance(entry, dict):
                    continue
                role = entry.get('role') or entry.get('job_title') or entry.get('title') or ''
                bullets = entry.get('bullets') or entry.get('highlights') or entry.get('achievements') or []
                if isinstance(bullets, str):
                    bullets = [bullets]
                if role or bullets:
                    normalized.append({
                        'role': role,
                        'company': entry.get('company', ''),
                        'period': entry.get('employment_dates') or entry.get('period') or entry.get('dates', ''),
                        'bullets': [str(b) for b in bullets if b],
                    })
            if normalized:
                data['experience_bullets_by_role'] = normalized

    # Normalize skills: flat list -> dict
    skills = data.get('skills')
    if isinstance(skills, list):
        data['skills'] = {'Technical Skills': [str(s) for s in skills if s]} if skills else {}
    elif skills is None:
        data['skills'] = {}

    # Normalize key_achievements: might be called achievements
    if 'key_achievements' not in data and 'achievements' in data:
        ach = data['achievements']
        if isinstance(ach, list):
            data['key_achievements'] = [str(a) for a in ach if a]

    # Ensure required keys exist
    data.setdefault('professional_summary', '')
    data.setdefault('experience_bullets_by_role', [])
    data.setdefault('skills', {})
    data.setdefault('key_achievements', [])
    data.setdefault('projects', [])

    return data

