def _sanitize_llm_result(data: dict) -> Optional[dict]:
    """Enforce resume rules on the parsed LLM result.

    - Summary must not contain contact info
    - Bullets must not be placeholders; cap at MAX_BULLETS_PER_ROLE per role
    - Achievements capped at MAX_ACHIEVEMENTS
    - Projects capped at MAX_PROJECTS
    - Strip residual markdown syntax from all text fields
    """
    if not data or not isinstance(data, dict):
        return None

    # Summary: reject if it's contact info
    summary = (data.get('professional_summary') or '').strip()
    if summary and _is_contact_info(summary):
        print('  [LLM] WARNING: summary looked like contact info — discarding')
        summary = ''
    data['professional_summary'] = summary

    # Experience bullets: filter placeholders, cap count, strip markdown
    exp_roles = data.get('experience_bullets_by_role', [])
    if isinstance(exp_roles, list):
        cleaned_roles = []
        for role_entry in exp_roles:
            if not isinstance(role_entry, dict):
                continue
            raw_bullets = role_entry.get('bullets', [])
            if isinstance(raw_bullets, str):
                raw_bullets = [raw_bullets]
            clean_bullets = []
            for b in raw_bullets:
                b_text = re.sub(r'\*\*|\*|__|_|^#+\s*', '', str(b)).strip()
                if b_text and not _is_placeholder_bullet(b_text):
                    clean_bullets.append(b_text)
            clean_bullets = clean_bullets[:MAX_BULLETS_PER_ROLE]
            if clean_bullets:
                role_entry['bullets'] = clean_bullets
                role_entry['role'] = re.sub(r'\*\*|\*|__|_', '', str(role_entry.get('role', ''))).strip()
                cleaned_roles.append(role_entry)
        data['experience_bullets_by_role'] = cleaned_roles

    # Legacy experience_bullets key
    if 'experience_bullets' in data and isinstance(data['experience_bullets'], list):
        data['experience_bullets'] = [
            re.sub(r'\*\*|\*|__|_', '', str(b)).strip()
            for b in data['experience_bullets']
            if b and not _is_placeholder_bullet(str(b))
        ][:MAX_BULLETS_PER_ROLE]

    # Skills: ensure dict format
    skills = data.get('skills')
    if isinstance(skills, list):
        skills = {'Technical Skills': [str(s) for s in skills if s]} if skills else {}
        data['skills'] = skills
    elif not isinstance(skills, dict):
        data['skills'] = {}

    # Achievements: cap and strip markdown
    achievements = data.get('key_achievements', [])
    if isinstance(achievements, list):
        data['key_achievements'] = [
            re.sub(r'\*\*|\*|__|_', '', str(a)).strip()
            for a in achievements
            if a and not _is_placeholder_bullet(str(a))
        ][:MAX_ACHIEVEMENTS]

    # Projects: cap count
    projects = data.get('projects', [])
    if isinstance(projects, list):
        cleaned_projects = []
        for p in projects[:MAX_PROJECTS]:
            if isinstance(p, dict):
                p['name'] = re.sub(r'\*\*|\*|__|_', '', str(p.get('name', ''))).strip()
                p['description'] = re.sub(r'\*\*|\*|__|_', '', str(p.get('description', ''))).strip()
                techs = p.get('technologies', [])
                if isinstance(techs, list):
                    p['technologies'] = [re.sub(r'\*\*|\*|__|_', '', str(t)).strip() for t in techs if t]
                cleaned_projects.append(p)
            elif isinstance(p, str) and p.strip():
                cleaned_projects.append({'name': p.strip(), 'description': '', 'technologies': []})
        data['projects'] = cleaned_projects

    return data


