    'professional summary', 'summary', 'core skills', 'technical skills', 'skills',
    'professional experience', 'experience', 'work experience', 'employment history',
    'key achievements', 'achievements', 'projects', 'technical project highlights',
    'education', 'certifications', 'languages', 'interests', 'community',
