async def _poll_usage():
    """Background task: poll umans usage API every 15 min, update global state."""
    while True:
        try:
            async with httpx.AsyncClient(timeout=15.0) as client:
                resp = await client.get(
                    UMANS_USAGE_URL,
                    headers={"Authorization": f"Bearer {UMANS_API_KEY}"}
                )
                if resp.status_code == 200:
                    data = resp.json()
                    usage = data.get("usage", {})
                    pb_list = usage.get("priority_budget", [])
                    frontier = next((b for b in pb_list if b.get("category") == "frontier"), {})

                    _usage_state["used_pct"] = frontier.get("used_pct", 0)
                    _usage_state["over_budget_today"] = frontier.get("over_budget_today", False)
                    _usage_state["mode"] = usage.get("service_mode", {}).get("current", "interactive")
                    _usage_state["resets_at"] = usage.get("service_mode", {}).get("resets_at")
                    _usage_state["requests_in_window"] = usage.get("requests_in_window", 0)
                    _usage_state["concurrent_sessions"] = usage.get("concurrent_sessions", 0)
                    _usage_state["last_poll"] = time.time()

                    # Append to usage log
                    log_entry = {
                        "timestamp": time.time(),
                        "used_pct": _usage_state["used_pct"],
                        "over_budget_today": _usage_state["over_budget_today"],
                        "mode": _usage_state["mode"],
                        "resets_at": _usage_state["resets_at"],
                        "requests_in_window": _usage_state["requests_in_window"],
                        "concurrent_sessions": _usage_state["concurrent_sessions"],
                    }
                    try:
                        with open(USAGE_LOG_PATH, "a") as f:
                            f.write(json.dumps(log_entry) + "\n")
                    except Exception:
                        pass

                    burst = "FULL BURST" if _is_full_burst() else f"throttle={_get_throttle_delay()}s"
                    print(f"[usage] used_pct={_usage_state['used_pct']}% mode={_usage_state['mode']} over_budget={_usage_state['over_budget_today']} {burst}")
        except Exception as e:
            print(f"[usage] poll error: {e}")

        await asyncio.sleep(USAGE_POLL_INTERVAL)

