    """Locate an Apply/Start-application button, piercing shadow DOM.

    Workday (and other modern ATS) render their buttons inside web components
    (shadow roots) that query_selector can't reach. This walks the live DOM
    including shadow roots and returns an ElementHandle (evaluate_handle —
    plain evaluate CANNOT return DOM elements) or None.
    """
    try:
        handle = await page.evaluate_handle('''() => {
            const KEY = /apply|start application|apply now|apply for/i;
            const walked = new Set();
            function text(el) { return (el.innerText || el.textContent || '').trim(); }
            function check(root) {
                const all = root.querySelectorAll ? Array.from(root.querySelectorAll('button, a, input[type=submit], [role=button]')) : [];
                for (const el of all) {
                    const t = text(el);
                    const aria = el.getAttribute && (el.getAttribute('aria-label') || '');
                    const val = el.getAttribute && (el.getAttribute('value') || '');
                    if (KEY.test(t) || KEY.test(aria || '') || KEY.test(val || '')) {
                        return el;
                    }
                }
                // recurse into shadow roots
                for (const el of (root.querySelectorAll ? Array.from(root.querySelectorAll('*')) : [])) {
                    if (el.shadowRoot && !walked.has(el.shadowRoot)) {
                        walked.add(el.shadowRoot);
                        const found = check(el.shadowRoot);
                        if (found) return found;
                    }
                }
                return null;
            }
            return check(document);
        }''')
        if handle is None:
