async def human_pause(min_ms: int = 800, max_ms: int = 3000):
    """Random human-like pause between actions to mimic reading/thinking time."""
    await asyncio.sleep(random.randint(min_ms, max_ms) / 1000)


async def click_follow_popup(page, el, popup_wait_ms: int = 6000):
    """Click `el`; if the click opens a NEW TAB/popup, return that page.

    Metaintro-style "Apply on employer site" links open the ATS in a new tab;
    without tracking it the bot keeps staring at the old page until timeout.
    Returns the new Page (loaded + front) or None when no popup appeared.
    Never raises on the no-popup path.
    """
    context = page.context
    evt = asyncio.ensure_future(context.wait_for_event('page', timeout=popup_wait_ms))
    try:
        try:
            await el.click(timeout=5000)
        except PlaywrightTimeout:
            await el.click(force=True, timeout=5000)
    except Exception:
        evt.cancel()
        raise
    try:
        new_page = await evt
        try:
            await new_page.wait_for_load_state('domcontentloaded', timeout=20000)
        except Exception:
            pass
        try:
            await new_page.bring_to_front()
        except Exception:
            pass
        return new_page
    except Exception:
        return None


