# ----------------------------------------------------- 1-second watcher

@staticmethod
def detect_stops(prev: Dict[str, str], current: Dict[str, str]) -> List[str]:
    """Panes that were working and are no longer working = just STOPPED."""
    return [p for p, now in current.items()
            if prev.get(p) == "working" and now != "working"]

def tick_once(self) -> Dict[str, int]:
    """Fast check (~1s cadence): react immediately to agents that stopped."""
    stats: Dict[str, int] = {}
    try:
        agents = self.backend.list_agents()
    except Exception:
        return stats  # herdr busy/unreachable — next tick retries
    seen = set()
    stops: List[Dict] = []
    for a in agents:
        pane = a.get("pane_id", "")
        seen.add(pane)
        status = a.get("status", "unknown")
        if pane in self.excludes:
            self._last_status[pane] = status
            continue
        if self.targets is not None and pane not in self.targets:
            self._last_status[pane] = status
            continue
        if a.get("agent") != "opencode":
            self._last_status[pane] = status
            continue
        prev = self._last_status.get(pane)
        if prev == "working" and status != "working":
            stops.append(a)
        self._last_status[pane] = status
    # user may close panes anytime — drop state for vanished ones
    gone = [p for p in list(self.last_nudge) + list(self._last_status)
            if p not in seen]
    for p in set(gone):
        self.last_nudge.pop(p, None)
        self.verified.discard(p)
        self._last_status.pop(p, None)
        self.on_event(f"[{p}] pane closed — dropped from supervision")
    if stops:
        stats["stopped_detected"] = len(stops)
        for a in stops:
            if time.time() - self.last_nudge.get(a["pane_id"], 0) < self.nudge_cooldown:
                stats["cooldown"] = stats.get("cooldown", 0) + 1
                continue
            action = self._handle_agent(a)
            stats[action] = stats.get(action, 0) + 1
            if action == "nudged":
                stats["stopped_handled"] = stats.get("stopped_handled", 0) + 1
        self._save_state()
    return stats

def run_forever(self):
    self.on_event(f"supervisor started · poll={self.poll_s}s · tick={self.tick_s}s · "
                  f"cooldown={self.nudge_cooldown}s · "
                  f"targets={sorted(self.targets) if self.targets is not None else 'all opencode'} · "
                  f"excluded={sorted(self.excludes) if self.excludes else 'none'}")
    next_full_pass = time.time() + self.poll_s
    while True:
        t0 = time.time()
        try:
            self.tick_once()
        except Exception as e:
            self.on_event(f"tick crashed (continuing): {e}")
        if time.time() >= next_full_pass:
            try:
                stats = self.pass_once()
                if stats.get("nudged") or stats.get("verify") or stats.get("judge_errors"):
                    self.on_event(f"full pass: {stats}")
            except Exception as e:
                self.on_event(f"pass crashed (continuing): {e}")
            next_full_pass = time.time() + self.poll_s
        time.sleep(max(0.2, self.tick_s - (time.time() - t0)))

