COPILOT_BASE = os.environ.get("AUTOFREE_COPILOT_BASE", "http://127.0.0.1:8789/v1")
COPILOT_MODEL = os.environ.get("AUTOFREE_COPILOT_MODEL", "copilot-gpt56")
KEYS_FILE = os.path.expanduser("~/Desktop/KEYS/api.txt")
JUNK_RE = re.compile(
    r"\b(wait a moment|please wait|hold on|try again|temporarily unavailable|"
    r"one moment|thinking[ .]{0,3}\.|standby)\b", re.I)


def _copilot_key() -> str:
    env = os.environ.get("AUTOFREE_COPILOT_KEY")
    if env:
        return env
    try:
        with open(KEYS_FILE) as f:
            txt = f.read()
        for line in txt.splitlines():
            if "TOOL_LAYER" in line and "=" in line:
                return line.split("=", 1)[1].strip().strip('"').strip("'")
        for line in txt.splitlines():
            if line.startswith("COPILOT_PROXY_API_KEY"):
                return line.split("=", 1)[1].strip().strip('"').strip("'")
    except Exception:
        pass
    return "sk-copilot-tool-layer"


def _looks_like_junk(text: str) -> bool:
    """Copilot/M365 sometimes answers with stall filler instead of real work."""
    if not text or len(text.strip()) < 15:
        return True
    stripped = text.strip()
    # pure-stall phrases only count when the reply is SHORT (long useful replies
    # may legitimately contain the words)
    if len(stripped) < 200 and JUNK_RE.search(stripped):
        return True
    return False


def _chat_completion(base_url: str, model: str, messages: List[Dict],
                     max_tokens: int = 1200, timeout: float = 90.0,
                     headers: Optional[Dict] = None) -> str:
    body = json.dumps({"model": model, "messages": messages,
                       "max_tokens": max_tokens, "temperature": 0})
    req = urllib.request.Request(
        base_url.rstrip("/") + "/chat/completions",
        data=body.encode("utf-8"),
        headers={"Content-Type": "application/json", **(headers or {})},
        method="POST")
    with urllib.request.urlopen(req, timeout=timeout) as r:
        data = json.loads(r.read().decode("utf-8", errors="replace"))
    msg = data["choices"][0]["message"]
    content = msg.get("content") or msg.get("reasoning_content") or ""
    if not content:
        raise JudgeError("empty completion")
    return content


def _chat_with_fallback(messages: List[Dict]) -> tuple:
    """Try the copilot proxy; on junk/failure fall back to our local model.
    Returns (reply_text | None, 'copilot' | 'local')."""
    try:
        reply = _chat_completion(
            COPILOT_BASE, COPILOT_MODEL, messages,
            headers={"Authorization": f"Bearer {_copilot_key()}"})
        if not _looks_like_junk(reply):
            return reply, "copilot"
    except Exception as e:
        _last_chain_error = str(e)
    else:
        _last_chain_error = "junk reply"
    # local fallback
    base = gj.detect_base_url()
    if not base:
        return None, "local-unreachable"
    try:
        listing = _chat_completion(base.rstrip("/") + "/models".replace("/models", "/models"), "", [])
    except Exception:
        pass
    try:
        reply = _chat_completion(base, "qwen2.5-coder-judge", messages,
                                 max_tokens=1200, timeout=gj.DEFAULT_TIMEOUT)
        if not _looks_like_junk(reply):
            return reply, "local"
    except Exception:
        pass
    return None, "failed"


