async def _shepherd_google_oauth(page, timeout_s: int = 45) -> bool:
    """Nudge the Google OAuth account chooser / consent / sign-in screens.

    The shared profile is normally logged into Gmail, so the chooser
    auto-continues. If Google instead asks for EMAIL or PASSWORD (session
    downgraded), fill them from the candidate profile and continue.
    Returns True once we're off accounts.google.com AND off a login wall.
    """
    for _ in range(timeout_s):
        await page.wait_for_timeout(1000)
        url = page.url.lower()
        if 'accounts.google.com' in url:
            # 1) Account tile (chooser)
            clicked = False
            for sel in ['div[data-email]', 'li[data-email]', '[data-email]']:
                try:
                    el = await page.query_selector(sel)
                    if el and await el.is_visible():
                        await el.click(timeout=3000)
                        clicked = True
                        break
                except Exception:
                    continue
            # 2) Email entry (session requires fresh sign-in)
            if not clicked:
                try:
                    esel = await page.query_selector(
                        'input[type="email"][autocomplete="username"], input[type="email"]')
                    if esel and await esel.is_visible():
                        await esel.fill(_GOOGLE_ACCOUNT_EMAIL)
                        nxt = await page.query_selector(
                            'div#identifierNext button, button:has-text("Next"), #identifierNext')
                        if nxt:
                            await nxt.click(timeout=3000)
                            await page.wait_for_timeout(2500)
                            clicked = True
                except Exception:
                    pass
            # 3) Password entry (if a password field appeared)
            if not clicked:
                try:
                    psel = await page.query_selector('input[type="password"]')
                    if psel and await psel.is_visible():
                        _pwd = os.environ.get('GOOGLE_ACCOUNT_PASSWORD', '')
                        if _pwd:
                            await psel.fill(_pwd)
                            nxt = await page.query_selector(
                                'div#passwordNext button, button:has-text("Next"), #passwordNext')
                            if nxt:
                                await nxt.click(timeout=3000)
                                await page.wait_for_timeout(2500)
                except Exception:
                    pass
            # 4) Consent / Continue buttons last.
            if not clicked:
                for sel in ['button:has-text("Continue")', 'button:has-text("Allow")',
                            'button:has-text("Next")']:
