const FREE_MODEL = process.env.ZEN_PROXY_FREE_MODEL || 'x-preview-f-free';
const RETRY_DELAYS = [15000, 30000, 60000, 120000, 180000];

// Concurrency gate: the free upstream Cloudflare-404s on bursts, so cap in-flight
// requests and queue the rest. Reject with 429 only if the queue itself overflows.
const MAX_CONCURRENT = +(process.env.ZEN_PROXY_MAX_CONCURRENT || 3);
const MAX_QUEUE = +(process.env.ZEN_PROXY_MAX_QUEUE || 20);
let active = 0, queued = 0;
const waiters = [];
function acquire() {
  if (active < MAX_CONCURRENT) { active++; return Promise.resolve(); }
  return new Promise(res => waiters.push(res));
}
function release() {
  if (waiters.length) { waiters.shift()(); } // unblock next waiter (already counts as active)
  else active--;
}

