let nextSlot = 0;                    // earliest allowed start time
let cooldownUntil = 0;               // global throttle cooldown gate

async function pacedSlot() {
  const now = Date.now();
  const wait = Math.max(nextSlot - now, cooldownUntil - now, 0);
  nextSlot = Math.max(now, cooldownUntil, nextSlot) + MIN_GAP_MS;
  if (wait > 0) await sleep(wait);
}

