async def _hittable(el) -> bool:
    """True when `el` is actually clickable — elementFromPoint at its center
    resolves to the element itself (Workday renders hidden duplicate forms;
    'is_visible' passes for covered copies whose clicks silently no-op)."""
    try:
        return await el.evaluate(
            '''el => {
                const r = el.getBoundingClientRect();
                if (r.width <= 0 || r.height <= 0) return false;
                const e = document.elementFromPoint(r.x + r.width / 2, r.y + r.height / 2);
                while (e) {
                    if (e === el) return true;
                    e = e.parentElement;
                }
                return false;
            }''')
    except Exception:
        return False

