async def _hittable(el) -> bool:
    """True when `el` can actually receive its click. Two pass conditions:
    (a) elementFromPoint at center resolves inside el, or
    (b) the topmost element is Workday's data-automation-id="click_filter"
        overlay — Workday's standard wrapper that FORWARDS the click to the
        control beneath; without this every Workday button failed the check.
    """
    try:
        return await el.evaluate(
            '''el => {
                const r = el.getBoundingClientRect();
                if (r.width <= 0 || r.height <= 0) return false;
                const e = document.elementFromPoint(r.x + r.width / 2, r.y + r.height / 2);
                if (!e) return false;
                let n = e;
                while (n) {
                    if (n === el) return true;
                    const d = n.getAttribute && n.getAttribute('data-automation-id');
                    if (d === 'click_filter') return true;
                    n = n.parentElement;
                }
                // topmost is a Workday click_filter anywhere on the page path
                let t = e;
                for (let i = 0; i < 4 && t; i++) {
                    if (t.getAttribute && t.getAttribute('data-automation-id') === 'click_filter') return true;
                    t = t.parentElement;
                }
                return false;
            }''')
    except Exception:
        return False

