def close_all_tabs():
    try:
        targets = json.load(urllib.request.urlopen(f"{CDP}/json", timeout=5))
    except Exception as e:  # browser not running — nothing to clean
        print(f"[CLEANUP] cannot reach {CDP}: {e}", file=sys.stderr)
        return 0
    ids = [t["id"] for t in targets if t.get("type") == "page" and t.get("id")]
    if not ids:
        # No tabs at all: open one blank tab so the window has something to show.
        try:
            urllib.request.urlopen(f"{CDP}/json/new?about:blank", timeout=5)
        except Exception:
            pass
        return 0
    if len(ids) == 1:
        # Only one tab — closing it would make Chrome exit. Leave it open so the
        # window survives; nothing to clean.
        return 0
    # Close every tab EXCEPT the first, keeping >=1 tab so the browser window
    # never dies (Chrome exits when its last tab is closed). The leftover first
    # tab is a harmless blank; the bot opens its own fresh tabs on top.
    closed = 0
    for tid in ids[1:]:
        try:
            urllib.request.urlopen(f"{CDP}/json/close/{tid}", timeout=5)
            closed += 1
        except Exception as e:
            print(f"[CLEANUP] close {tid} failed: {e}", file=sys.stderr)
    return closed

