def _try_local(messages: list[dict], *, temperature: float, max_tokens: int,
               timeout: float) -> Optional[dict]:
    """Local Qwen3-8B workhorse — fast, free, private, no rate limits.

    Primary tier for lightweight calls (classification, field detection, short
    answers, relevance, browser tasks). Falls through to Copilot/Mistral on
    failure so quality is never silently dropped.
    """
    started = time.time()
    try:
        client = openai.OpenAI(api_key="not-needed", base_url=LOCAL_LLM_BASE_URL, max_retries=0)
    except Exception:
        return None
    try:
        resp = client.chat.chat.completions.create(
            model=LOCAL_LLM_MODEL,
            messages=messages,
            temperature=temperature,
            max_tokens=max_tokens,
            timeout=min(timeout, LOCAL_LLM_TIMEOUT_SECONDS),
        )
    except Exception as _e:
        print(f"[LLM-ROUTER] local/{LOCAL_LLM_MODEL} raised {type(_e).__name__} — skipping local tier")
        return None
    try:
        content = (resp.choices[0].message.content or "").strip()
    except Exception:
        return None
    if not content:
        return None
    elapsed_ms = int((time.time() - started) * 1000)
    print(f"[LLM-ROUTER] local/{LOCAL_LLM_MODEL} responded in {elapsed_ms}ms")
    return {
        "content": content,
        "scoring_method": "local",
        "model": LOCAL_LLM_MODEL,
        "elapsed_ms": elapsed_ms,
    }


