_RAG_EXP_BULLETS_CACHE = None


def _rag_experience_bullets():
    """Parse the canonical 'Professional Experience:' block from
    comprehensive_rag_data.md into a list of {role, bullets}. GUARANTEED
    fallback source so a resume is never left with an empty EXPERIENCE section."""
    global _RAG_EXP_BULLETS_CACHE
    if _RAG_EXP_BULLETS_CACHE is not None:
        return _RAG_EXP_BULLETS_CACHE
    _result = []
    _rag_path = RAW_DATA_DIR / 'comprehensive_rag_data.md'
    if not _rag_path.exists():
        _rag_path = RASJOBBOT_DATA_DIR.parent / 'data_folder' / 'raw_data' / 'comprehensive_rag_data.md'
    if _rag_path.exists():
        try:
            _content = _rag_path.read_text(encoding='utf-8')
            _m = re.search(
                r'(?im)^professional experience:\s*$(.*?)(?=^\n?[A-Z][a-z]+:|^education:|^certifications:|\Z)',
                _content, re.DOTALL,
            )
            _block = _m.group(1) if _m else ''
            for _line in _block.splitlines():
                _line = _line.strip()
                if not _line.startswith('-'):
                    continue
                _line = _line[1:].strip()
                if '|' not in _line:
                    continue
                _parts = [p.strip() for p in _line.split('|')]
                _role = _parts[1] if len(_parts) > 1 else ''
                _desc = _parts[-1]
                if '—' in _desc:
                    _desc = _desc.split('—', 1)[1].strip()
                elif ' - ' in _desc:
                    _desc = _desc.split(' - ', 1)[1].strip()
                if not _role or not _desc:
                    continue
                _sents = [s.strip() for s in re.split(r'(?<=[.!?])\s+', _desc) if s.strip()]
                _bullets = _sents[:3] if _sents else [_desc]
                _result.append({'role': _role, 'bullets': _bullets})
        except Exception:
            pass
    _RAG_EXP_BULLETS_CACHE = _result
    return _result


def _fill_missing_experience_bullets(india_exp, canada_exp, rag_bullets) -> None:
    """Backfill any experience entry lacking bullets from rag_bullets (matched by
    role name). Mutates lists in place; guarantees non-empty EXPERIENCE."""
    if not rag_bullets:
        return
    for _exp in list(india_exp) + list(canada_exp):
        if _exp.get('bullets'):
            continue
        _title = (str(_exp.get('title') or '')).lower()
        if not _title:
            continue
        for _rb in rag_bullets:
            _rrole = str(_rb.get('role') or '').lower()
            if not _rrole:
                continue
            if (_rrole == _title or _rrole in _title or _title in _rrole
                    or (_rrole.split()[0] in _title) or (_title.split()[0] in _rrole)):
                _exp['bullets'] = list(_rb.get('bullets', []))
                break


def _experience_populated(data) -> bool:
    """True if a parsed resume dict has at least one non-empty experience bullet."""
    if not data:
        return False
    _br = data.get('experience_bullets_by_role') or []
    if not _br:
        return False
    return any((b.get('bullets') if isinstance(b, dict) else None) for b in _br)


def _validate_resume_structured(structured, job_title: str = '') -> list:
    """Return a list of issue strings for a built resume (empty list = healthy)."""
    _issues = []
    _exp = structured.get('experience') or []
    _total = sum(len(e.get('bullets', [])) for e in _exp)
    if _total == 0:
        _issues.append('EXPERIENCE_EMPTY')
    if not str(structured.get('summary') or '').strip():
        _issues.append('SUMMARY_EMPTY')
    if not (structured.get('skills') or {}):
        _issues.append('SKILLS_EMPTY')
    return _issues


def _critique_resume(structured, job_title: str, company: str, jd: str) -> dict:
    """Final LLM critique — runs even when validation passes. Logs any major
    flaws so they can be inspected and fixed. Returns a dict."""
    _sys = (
        'You are a strict senior resume reviewer. Given a structured resume JSON, '
        'identify ANY major flaws: empty sections, missing experience bullets, broken/'
        'garbled text, formatting problems, factual inconsistencies, or missing contact '
        'info. Respond with STRICTLY VALID JSON only: '
        '{"ok": true/false, "major_flaws": ["..."], "minor_notes": ["..."]}.'
    )
    _user = (
        f"TARGET JOB: {job_title} @ {company}\n\n"
        f"RESUME JSON:\n{json.dumps(structured, ensure_ascii=False)[:6000]}"
    )
    try:
        _c = _call_llm(_sys, _user)
        if _c:
            _log_llm_raw(job_title, 'CRITIQUE', _c)
            _d = _parse_json_resume(_c)
            if _d:
                return _d
    except Exception as _e:
        _heal_log(job_title, f'critique call failed: {_e}')
    return {'ok': True, 'major_flaws': [], 'minor_notes': ['critique skipped']}


