_QA_LOG_PATH = os.path.join(BASE_DIR, 'form_qa_log.jsonl')

# ── Learned field rules (non-LLM form-fill feedback loop) ──────────────────
# When the LLM successfully fills a field the deterministic/heuristic pass
# missed, we persist (normalized-question -> answer) here. On every later run
# the non-LLM pass consults these rules FIRST, so over time the LLM is needed
# less and less. Identity fields are stored as profile tokens ({email}) so the
# rule generalizes across jobs instead of hard-coding one answer.
_FIELD_RULES_PATH = os.path.join(BASE_DIR, 'form_field_rules.json')
_field_rules_cache: dict | None = None


def _norm_label(label: str) -> str:
    import re as _re
    s = (label or '').lower().strip()
    s = _re.sub(r'[^a-z0-9]+', ' ', s).strip()
    return s


def _load_field_rules() -> dict:
    global _field_rules_cache
    if _field_rules_cache is not None:
        return _field_rules_cache
    try:
        if os.path.exists(_FIELD_RULES_PATH):
            with open(_FIELD_RULES_PATH, 'r', encoding='utf-8') as f:
                _field_rules_cache = json.load(f)
        else:
            _field_rules_cache = {}
    except Exception:
        _field_rules_cache = {}
    return _field_rules_cache


def _save_field_rules(rules: dict):
    global _field_rules_cache
    _field_rules_cache = rules
    try:
        with open(_FIELD_RULES_PATH, 'w', encoding='utf-8') as f:
            json.dump(rules, f, indent=2, ensure_ascii=False)
    except Exception as e:
        print(f'  [FORM-RULES] save error: {e}')


def _profile_token_for(value, resume_data) -> tuple:
    """Return (literal, token). token is set when value equals a profile field."""
    if not value:
        return value, None
    v = str(value).strip().lower()
    mapping = {
        'email': resume_data.get('email'),
        'phone': resume_data.get('phone'),
        'name': resume_data.get('name'),
        'linkedin': resume_data.get('linkedin') or resume_data.get('website'),
        'location': resume_data.get('location') or resume_data.get('city'),
    }
    for token, prof_val in mapping.items():
        if prof_val and str(prof_val).strip().lower() == v:
            return None, token
    return value, None


def _learn_field(label, value, ftype, resume_data):
    """Persist an LLM-discovered field so future non-LLM passes can fill it."""
    try:
        nl = _norm_label(label)
        if not nl or value is None or str(value).strip() == '':
            return
        rules = _load_field_rules()
        literal, token = _profile_token_for(value, resume_data)
        rules[nl] = {
            'value': literal if literal is not None else '',
            'token': token or '',
            'type': ftype or 'text',
        }
        _save_field_rules(rules)
        print(f'  [FORM-RULES] learned {label!r} -> {token or value!r}')
    except Exception as e:
        print(f'  [FORM-RULES] learn error: {e}')


def _resolve_rule_value(rule: dict, resume_data) -> str:
    token = rule.get('token')
    if token:
        return str(resume_data.get(token) or '')
    return str(rule.get('value') or '')


async def _apply_learned_rules(page, resume_data) -> int:
    """Non-LLM pass: fill empty visible fields from previously-learned rules.

    Returns number of fields filled. Runs BEFORE the LLM so discovered fields
    never need the model again.
    """
    rules = _load_field_rules()
    if not rules:
        return 0
    filled = 0
    try:
        for el in await page.query_selector_all(
            'input:not([type="hidden"]):not([type="file"]):not([type="radio"]):not([type="checkbox"]), select, textarea'
        ):
            try:
                if not await el.is_visible() or not await el.is_enabled():
                    continue
                if (await el.evaluate('el => (el.value || "").trim()')):
                    continue
                label = (await _get_label_for_input(page, el)).strip()
                rule = rules.get(_norm_label(label))
                if not rule:
                    continue
                val = _resolve_rule_value(rule, resume_data)
                if val == '':
                    continue
                await el.fill(val)
                _log_qa_entry(label, val, rule.get('type') or 'text', 'learned-rule',
                              field_name=(await el.get_attribute('name') or ''))
                filled += 1
            except Exception:
                continue
        # radio / checkbox groups
        by_name: dict = {}
        for el in await page.query_selector_all('input[type="radio"], input[type="checkbox"]'):
            try:
                if not await el.is_visible():
                    continue
                nm = (await el.get_attribute('name') or '').strip()
                if nm:
                    by_name.setdefault(nm, []).append(el)
            except Exception:
                continue
        for nm, els in by_name.items():
            try:
                q = _norm_label(await _get_group_question_text(page, els[0]))
                rule = rules.get(q)
                if not rule:
                    continue
                if rule.get('token') == 'checkbox' or rule.get('type') == 'checkbox':
                    for el in els:
                        if not await el.evaluate('el => !!el.checked'):
                            await el.check()
                            filled += 1
                    continue
                want = str(rule.get('value') or '').strip().lower()
                if not want:
                    continue
                for el in els:
                    ot = (await _get_option_text(page, el)).strip().lower()
                    ov = (await el.get_attribute('value') or '').strip().lower()
                    if want in (ot, ov) or ot in want or ov in want:
                        if not await el.evaluate('el => !!el.checked'):
                            await el.check()
                            filled += 1
                        break
            except Exception:
                continue
    except Exception:
        pass
    if filled:
        print(f'  [FORM] learned-rules filled {filled} field(s)')
    return filled


async def _page_has_unfilled_questions(page) -> bool:
    """True if visible empty fillable fields with a label (real questions) remain.

    Used to (a) decide whether the LLM fallback is needed and (b) avoid logging a
    false 'form_fill_failed' on steps that have no questions (e.g. the
    resume-selection module, which is just a file upload).
    """
    try:
        for el in await page.query_selector_all(
            'input:not([type="hidden"]):not([type="file"]), select, textarea'
        ):
            try:
                if not await el.is_visible():
                    continue
                if (await el.evaluate('el => (el.value || "").trim()')):
                    continue
                if (await _get_label_for_input(page, el)).strip():
                    return True
            except Exception:
                continue
        by_name: dict = {}
        for el in await page.query_selector_all('input[type="radio"], input[type="checkbox"]'):
            try:
                if not await el.is_visible():
                    continue
                nm = (await el.get_attribute('name') or '').strip()
                if nm:
                    by_name.setdefault(nm, 0)
                    if await el.evaluate('el => !!el.checked'):
                        by_name[nm] += 1
            except Exception:
                continue
        for nm, checked in by_name.items():
            if checked == 0:
                return True
    except Exception:
        pass
    return False


