    m = get_model()
    cells = grid_cells(grid_bgr, 3)
    confs = {}
    for i, cell in enumerate(cells):
        res = m.predict(cell, verbose=False)[0]
        if res.probs is not None:
            confs[i] = float(res.probs.data[target_cls])
        else:
            confs[i] = 0.0
    return confs

