class PaidCaptchaService:
    """Last-resort fallback using paid CAPTCHA solving services.

    Supports Capsolver and 2captcha for reCAPTCHA/hCaptcha token-based challenges.
    Requires CAPSOLVER_API_KEY or TWOCAPTCHA_API_KEY environment variable.
    """

    def __init__(self):
        self.capsolver_key = os.environ.get("CAPSOLVER_API_KEY")
        self.twocaptcha_key = os.environ.get("TWOCAPTCHA_API_KEY")
        self.enabled = bool(self.capsolver_key or self.twocaptcha_key)

    async def solve(self, page) -> bool:
        if not self.enabled:
            return False
        page_url = page.url
        site_key = await self._extract_sitekey(page)
        if not site_key:
            print("[CAPTCHA] Paid service: no sitekey found")
            return False
        print(f"[CAPTCHA] Paid service: sitekey={site_key[:20]}...")
        token = None
        if self.capsolver_key:
            token = await self._solve_capsolver(page_url, site_key)
        if not token and self.twocaptcha_key:
            token = await self._solve_twocaptcha(page_url, site_key)
        if not token:
            return False
        return await self._inject_token(page, token)

    async def _extract_sitekey(self, page):
        # Try data-sitekey on visible recaptcha/hcaptcha containers
        for attr in ["data-sitekey", "data-callback"]:
            for selector in [".g-recaptcha", "[class*='grecaptcha']", ".h-captcha", "[class*='hcaptcha']"]:
                try:
                    el = await page.query_selector(f"{selector}[{attr}]")
                    if el:
                        val = await el.get_attribute(attr)
                        if val:
                            return val
                except Exception:
                    pass
