    def _capsolver_create_and_poll(self, payload: dict, timeout: int = 120) -> Optional[str]:
        import time as _t
        create = self._post_json(f"{self.API_URL}/createTask", payload)
        if not create.get("taskId"):
            print(f"[CAPTCHA] Capsolver createTask failed: {create}")
            return None
        task_id = create["taskId"]
        start = _t.time()
        while _t.time() - start < timeout:
            _t.sleep(3)
            result = self._post_json(
                f"{self.API_URL}/getTaskResult",
                {"clientKey": self.capsolver_key, "taskId": task_id},
