            status = result.get("status")
            if status == "ready":
                solution = result.get("solution") or {}
                for key in ("gRecaptchaResponse", "token", "captcha", "turnstile"):
                    val = solution.get(key)
                    if isinstance(val, str) and val:
                        return val
                return None
            if status == "failed":
                print(f"[CAPTCHA] Capsolver task failed: {result.get('errorDescription')}")
                return None
        print("[CAPTCHA] Capsolver task timed out")
        return None

