  // Special-case home page (single index at SRC root, plus per-locale roots)
  let file, p;
  if (slug === 'home') {
    if (locale === 'en') {
      p = path.join(SRC, 'home.html');
      if (fs.existsSync(p)) return fs.readFileSync(p, 'utf8').toString();
    }
    file = locale === 'en' ? 'home.html' : `${locale}/_root.html`;
  } else if (slug === '') {
    file = `${locale}/_root.html`;
  } else {
    file = `${locale}/${slug}.html`;
  }
  p = path.join(SRC, file);
  if (!fs.existsSync(p)) return null;
  return fs.readFileSync(p, 'utf8').toString();
}

