/**
 * Web Chat Browser Controller
 * Communicates with Kimi K3, GLM 5.3 (ChatGLM), ChatGPT (GPT Deep Thinker / GPT-5)
 * and Qwen3.8-Max (Thinking) via Chrome DevTools Protocol (CDP).
 * All browser seats run inside the council's own window-broker lease so they
 * never touch another agent's tabs.
 */

const CDP = require('chrome-remote-interface');
const net = require('net');
const { BrokerLease } = require('./broker-lease');

const MODEL_URLS = {
  'kimi-k3': 'https://www.kimi.com/',
  'glm-5.3': 'https://chatglm.cn/main/alltoolsdetail?lang=zh',
  'gpt-deep-thinker': 'https://chatgpt.com/',
  'qwen3.8-max': 'https://chat.qwen.ai/?temporary-chat=true'
};

const QWEN_URL = MODEL_URLS['qwen3.8-max'];

class WebChatBrowserController {
  constructor(options = {}) {
    this.host = options.host || '127.0.0.1';
    this.port = options.port || 9222;
    this.lease = options.lease || new BrokerLease({ prefer: 'cloak' });
    this.cdpConnect = options.cdp || null;
    this.responseTimeoutMs = options.responseTimeoutMs || 120000;
  }

  async isPortOpen(port, host) {
    return new Promise((resolve) => {
      const socket = new net.Socket();
      socket.setTimeout(1000);
      socket.once('error', () => { socket.destroy(); resolve(false); });
      socket.once('timeout', () => { socket.destroy(); resolve(false); });
      socket.connect(port, host, () => { socket.end(); resolve(true); });
    });
  }

  async _connect(target) {
    if (this.cdpConnect) return this.cdpConnect(target);
    return CDP(target);
  }

  async _leaseForPool() {
    if (!this.lease.acquired) await this.lease.acquire();
    return this.lease.acquired ? this.lease : null;
  }

  async findOrCreateTab(modelKey) {
    const url = MODEL_URLS[modelKey] || 'https://www.google.com';
    const lease = await this._leaseForPool();

    if (lease) {
      const targetId = await lease.openTab(url);
      if (!targetId) throw new Error(`[WebChatBrowser] Broker did not return a target for ${modelKey}`);
      const client = await this._connect({ host: this.host, port: lease.cdpUrl, target: targetId });
      await client.Page.enable();
      await client.Runtime.enable();
      await client.DOM.enable();
      return client;
    }

    const pool = this.lease.cdpUrl;
    const host = pool.replace(/^https?:\/\//, '').split(':')[0];
    const port = parseInt(pool.replace(/^https?:\/\//, '').split(':')[1], 10) || 9223;
    const targets = await CDP.List({ host, port });
    const urlPattern = url.replace(/^https?:\/\//, '').split('/')[0];
    let target = targets.find(t => t.url && t.url.includes(urlPattern) && t.type === 'page');

    if (!target) {
      console.error(`[WebChatBrowser] Creating new tab for ${modelKey} on raw pool ${pool}`);
      target = await CDP.New({ host, port, url });
    } else {
      console.error(`[WebChatBrowser] Reusing existing tab for ${modelKey}: ${target.id}`);
    }

    const client = await this._connect({ host, port, target: target.id });
    await client.Page.enable();
    await client.Runtime.enable();
    await client.DOM.enable();
    return client;
  }

  sleep(ms) {
    return new Promise(resolve => setTimeout(resolve, ms));
  }

  async ask(modelKey, message) {
    let client = null;
    try {
      client = await this.findOrCreateTab(modelKey);
      if (modelKey === 'kimi-k3') {
        return await this.sendKimiMessage(client, message);
      } else if (modelKey === 'glm-5.3') {
        return await this.sendGlmMessage(client, message);
      } else if (modelKey === 'gpt-deep-thinker') {
        return await this.sendGptMessage(client, message);
      } else if (modelKey === 'qwen3.8-max') {
        return await this.sendQwenMessage(client, message);
      } else {
        throw new Error(`Unsupported web chat model: ${modelKey}`);
      }
    } finally {
      if (client) {
        try { await client.close(); } catch (e) {}
      }
    }
  }

  async sendQwenMessage(client, message) {
    const { Runtime, Page } = client;
    const evaluate = async (expression) => {
      const res = await Runtime.evaluate({ expression, returnByValue: true });
      return res && res.result ? res.result.value : null;
    };

    await Page.navigate({ url: QWEN_URL });
    await this.sleep(2500);

    for (let i = 0; i < 20; i++) {
      const ready = await evaluate(`(() => !!document.querySelector('textarea'))()`);
      if (ready) break;
      await this.sleep(1000);
    }

    const loginRequired = await evaluate(`(() => {
      const t = (document.body.innerText || '');
      const hit = t.includes('登录') || t.includes('Log in') || t.includes('Login') ||
                  t.includes('Sign in') || t.includes('登录以继续');
      if (!hit) return false;
      return !document.querySelector('textarea');
    }) () /*__QWEN_LOGIN_CHECK__*/`);
    if (loginRequired) {
      return `[Qwen3.8-Max Web Chat] Login required: open ${QWEN_URL} in the shared CloakBrowser profile (cloakbrowser-login https://chat.qwen.ai/) and sign in with the Qwen account. Nothing was sent.`;
    }

    await evaluate(`(() => {
      const trigger = document.querySelector('.wms-trigger, [class*="model-switch"], [class*="model-selector"]');
      if (trigger) trigger.click();
      return true;
    })()`);
    await this.sleep(800);

    const currentModel = await evaluate(`(() => {
      const el = document.querySelector('.wms-trigger, [class*="model-name"], [class*="model-switch"]');
      return el ? (el.innerText || '').trim() : '';
    })()`);
    if (currentModel && !/qwen3\.8-max/i.test(currentModel)) {
      await evaluate(`(() => {
        const nodes = Array.from(document.querySelectorAll('[role="menuitem"], [role="option"], li, button, div'));
        const target = nodes.find(n => /qwen3\.8-max/i.test((n.innerText || '').trim()) && (n.innerText || '').trim().length < 40);
        if (target) { target.click(); return true; }
        return false;
      })()`);
      await this.sleep(1200);
    }

    const thinkingEnabled = await evaluate(`(() => {
      const cur = document.querySelector('.wms-trigger');
      if (cur && /thinking/i.test(cur.innerText || '')) return true;
      const nodes = Array.from(document.querySelectorAll('[role="menuitem"], [role="option"], li, button, div, span'));
      const target = nodes.find(n => /^(thinking|深度思考|思考)$/i.test((n.innerText || '').trim()));
      if (target) { target.click(); return true; }
      return false;
    })()`);
    if (!thinkingEnabled) {
      console.error('[QwenSeat] Could not confirm Thinking mode; asking anyway');
    }
    await this.sleep(500);

    const typed = await evaluate(`(() => {
      const el = document.querySelector('textarea');
      if (!el) return false;
      el.focus();
      const setter = Object.getOwnPropertyDescriptor(HTMLTextAreaElement.prototype, 'value').set;
      setter.call(el, ${JSON.stringify(message)});
      el.dispatchEvent(new Event('input', { bubbles: true }));
      el.dispatchEvent(new Event('change', { bubbles: true }));
      return el.value === ${JSON.stringify(message)};
    })() /*__QWEN_TYPED__*/`);
    if (!typed) {
      return `[Qwen3.8-Max Web Chat] Could not type into the composer at ${QWEN_URL}. Login may have expired.`;
    }
    await this.sleep(400);

    const sent = await evaluate(`(() => {
      const btn = document.querySelector('button[aria-label="Send"], button[aria-label*="send" i], button[type="submit"]');
      if (btn && !btn.disabled) { btn.click(); return 'button'; }
      const el = document.querySelector('textarea');
      if (el) {
        el.dispatchEvent(new KeyboardEvent('keydown', { key: 'Enter', code: 'Enter', keyCode: 13, which: 13, bubbles: true }));
        return 'enter';
      }
      return 'none';
    })() /*__QWEN_SENT__*/`);
    if (sent === 'none') {
      return `[Qwen3.8-Max Web Chat] Composer present but no send control at ${QWEN_URL}.`;
    }

    const response = await this.waitForStreamingResponse(client, [
      '.chat-message-assistant .markdown-body',
      '[class*="assistant"] .markdown-body',
      '.markdown-body',
      '[class*="message"][class*="assistant"]',
      '.response-content'
    ], this.responseTimeoutMs);
    return response;
  }

