BRAIN_GOAL_MAX_CHARS = 2000
BRAIN_TOOL_SUMMARY_MAX_CHARS = 4000
BRAIN_USER_MAX_CHARS = 2400
BRAIN_LATEST_USER_MAX_CHARS = 4000
BRAIN_ASSISTANT_MAX_CHARS = 1200
BRAIN_TOOL_MAX_CHARS = 2500


def _clip_text(text: str, max_chars: int, *, preserve_tail: bool = False) -> str:
    if max_chars <= 0:
        return ""
    if len(text) <= max_chars:
        return text
    if preserve_tail:
        marker = "...[truncated]..."
        if max_chars <= len(marker):
            return text[-max_chars:]
        return marker + text[-(max_chars - len(marker)):]
    if max_chars <= 3:
        return text[:max_chars]
    return text[:max_chars - 3].rstrip() + "..."


def _serialized_brain_size(messages: list[dict[str, Any]]) -> int:
    return len(json.dumps(messages, ensure_ascii=True).encode("utf-8"))


def _brain_system_prompt(
    primary_goal: str,
    tools_summary: str,
    has_tool_obs: bool,
    latest_user_text: str,
    budget_chars: int,
) -> str:
    goal = _clip_text(primary_goal, BRAIN_GOAL_MAX_CHARS)
    tool_summary = _clip_text(tools_summary, BRAIN_TOOL_SUMMARY_MAX_CHARS)
    full_prompt = (
        "You are the Senior Engineer / Brain of this autonomous agent.\n"
        f"Primary User Objective: {goal}\n"
    )
    if tool_summary:
        full_prompt += f"\nAvailable execution tools:\n{tool_summary}\n"
    full_prompt += (
        "\nUNIVERSAL AUTONOMOUS DIRECTIVES:\n"
        "1. ZERO CLARIFYING QUESTIONS: Never ask the user questions, confirmations, or permissions. "
        "Discover facts by inspecting files, processes, configs, and endpoints using your execution tools. "
        "Make the most robust technical inference and proceed.\n"
        "2. ABSOLUTE ZERO REFUSALS: Never refuse or state that you lack capabilities. You have full terminal/code execution. "
        "Every technical obstacle has a solution (CLI tools, downloading binaries, building from source, piping inputs, writing scripts).\n"
        "3. FAILURE IS DATA — RELENTLESS STRUGGLE THROUGH ROADBLOCKS: If an action or tool fails or returns an error, "
        "NEVER stop or report failure. Analyze the stderr/output, diagnose the root constraint (e.g. interactive stdin prompt, "
        "missing flag, process conflict, pipe error), and immediately output the next action with an alternative strategy in your code block.\n"
        "4. ACTION FORMAT: When an action or command is needed, YOU MUST ALWAYS provide the exact code or command in a markdown code block "
        "(```bash ... ``` or ```python ... ``` for `ipython`).\n"
        "5. DEFINITION OF DONE: Only output a final text answer when you have verified that the user's objective is fully accomplished "
        "with live command verification evidence. Never output conversational advice when actions are still pending."
    )
    if not has_tool_obs:
        full_prompt += (
            "\n\n⚡ MANDATORY FIRST ACTION:\n"
            "No commands have been executed yet for this task. You have full terminal/system execution.\n"
            "You MUST output the first diagnostic or execution action in a markdown code block (```bash ... ``` or ```python ... ```).\n"
            "DO NOT output conversational excuses or claim the task is verified/impossible without executing commands first.\n"
        )
    else:
        full_prompt += (
            "\n\n⚡ NEXT ACTION DIRECTIVE:\n"
            "Review the latest tool observation. If the user's objective is not yet fully accomplished, "
            "formulate the next diagnostic or execution step and output the command in a markdown code block (```bash ... ``` or ```python ... ```).\n"
            "When updating/installing software, always test the tool's built-in update commands (e.g. `tool update`, `echo y | tool update`) "
            "or release endpoints. Never report an old version as complete if the task asked to update it!\n"
        )

    latest_anchor = _clip_text(
        latest_user_text,
        min(BRAIN_LATEST_USER_MAX_CHARS, max(32, budget_chars // 8)),
        preserve_tail=True,
    )
    anchor_messages = [{"role": "user", "content": latest_anchor}] if latest_anchor else []
    if _serialized_brain_size([{"role": "system", "content": full_prompt}, *anchor_messages]) <= budget_chars:
        return full_prompt

    compact_prompt = ""
    for divisor in (4, 5, 6, 8):
        compact_goal = _clip_text(primary_goal, max(32, min(BRAIN_GOAL_MAX_CHARS, budget_chars // divisor)))
        compact_tools = _clip_text(tools_summary, max(32, min(BRAIN_TOOL_SUMMARY_MAX_CHARS, budget_chars // divisor)))
        compact_prompt = (
            "You are the Senior Engineer / Brain of this autonomous agent.\n"
            f"Primary User Objective: {compact_goal}\n"
        )
        if compact_tools:
            compact_prompt += f"Available execution tools:\n{compact_tools}\n"
        compact_prompt += "Use the newest user request and current observations. Continue autonomously and verify the result."
        if _serialized_brain_size([{"role": "system", "content": compact_prompt}, *anchor_messages]) <= budget_chars:
            return compact_prompt

    while len(compact_prompt) > 32:
        compact_prompt = _clip_text(compact_prompt, max(32, len(compact_prompt) * 4 // 5))
        if _serialized_brain_size([{"role": "system", "content": compact_prompt}, *anchor_messages]) <= budget_chars:
            return compact_prompt
    return ""


def _fit_brain_turn(
    turn: dict[str, Any],
    prefix: list[dict[str, Any]],
    budget_chars: int,
) -> dict[str, Any] | None:
    content = str(turn.get("content", ""))
    low = 0
    high = len(content)
    fitted: dict[str, Any] | None = None
    while low <= high:
        middle = (low + high) // 2
        candidate = {**turn, "content": _clip_text(content, middle, preserve_tail=True)}
        if _serialized_brain_size([*prefix, candidate]) <= budget_chars:
            fitted = candidate
            low = middle + 1
        else:
            high = middle - 1
    return fitted


def _distill_messages_for_brain(
    messages: list[dict[str, Any]],
    tools_summary: str = "",
    budget_chars: int = 18000,
) -> list[dict[str, Any]]:
    if not messages or budget_chars <= 0:
        return []

    primary_goal = _extract_primary_goal(messages)
    latest_user_text = _last_user_text(messages)
    has_tool_obs = any(m.get("role") in ("tool", "function") for m in messages)
    system_prompt = _brain_system_prompt(
        primary_goal,
        tools_summary,
        has_tool_obs,
        latest_user_text,
        budget_chars,
    )
    if not system_prompt:
        return []

    last_user_index: int | None = None
    for index in range(len(messages) - 1, -1, -1):
        if messages[index].get("role") == "user":
            content = _message_text(messages[index].get("content"))
            if "<harness_state>" in content:
                content = content.split("</harness_state>")[-1].strip()
            if content and not _is_harness_digest(content):
                last_user_index = index
                break

    formatted_turns: list[dict[str, Any]] = []
    latest_turn: dict[str, Any] | None = None
    for index, message in enumerate(messages):
        role = message.get("role")
        if role == "system":
            continue
        content = _message_text(message.get("content"))

        if role == "user":
            if "<harness_state>" in content:
                content = content.split("</harness_state>")[-1].strip()
            elif _is_harness_digest(content):
                continue
            if not content:
                continue
            if index == last_user_index:
                content = _clip_text(content, BRAIN_LATEST_USER_MAX_CHARS, preserve_tail=True)
                turn = {"role": "user", "content": content}
                latest_turn = turn
            else:
                turn = {"role": "user", "content": _clip_text(content, BRAIN_USER_MAX_CHARS)}
            formatted_turns.append(turn)

        elif role == "assistant":
            if content:
                formatted_turns.append({
                    "role": "assistant",
                    "content": _clip_text(content, BRAIN_ASSISTANT_MAX_CHARS),
                })

        elif role == "tool":
            observation = _clip_text(content, BRAIN_TOOL_MAX_CHARS, preserve_tail=True)
            formatted_turns.append({
                "role": "user",
                "content": f"Observation (Tool Execution Result):\n{observation}",
            })

    system_message = {"role": "system", "content": system_prompt}
    selected_turns: list[dict[str, Any]] = []
    for turn in reversed(formatted_turns):
        candidate = [system_message, turn, *selected_turns]
        if _serialized_brain_size(candidate) <= budget_chars:
            selected_turns.append(turn)
            continue
        if turn is latest_turn:
            fitted = _fit_brain_turn(turn, [system_message, *selected_turns], budget_chars)
            if fitted is not None:
                selected_turns.append(fitted)

    selected_turns.reverse()
    return [system_message, *selected_turns]

