def _render_chat_message_units(
    messages: Sequence[ChatMessage],
    fixed_parts: Sequence[str] = (),
) -> list[PromptUnit]:
    fixed = [str(part) for part in fixed_parts if part]
    newest_user_index = max(
        (index for index, message in enumerate(messages) if message.role == "user"),
        default=-1,
    )
    tool_call_groups: dict[str, str] = {}
    for index, message in enumerate(messages):
        if message.role != "assistant" or not message.tool_calls:
            continue
        group_id = f"chat-tool-group:{index}"
        for tool_call in message.tool_calls:
            call_id = tool_call.get("id")
            if call_id:
                tool_call_groups[str(call_id)] = group_id

    units: list[PromptUnit] = []
    for index, message in enumerate(messages):
        cleaned = _strip_tool_capability_blocks(str(message.content or ""))
        if message.role == "system":
            fixed.append(f"[System instruction]: {cleaned}")
            continue
        if message.role == "user":
            units.append(
                PromptUnit(
                    text=f"User: {cleaned}",
                    role=message.role,
                    protected=index == newest_user_index,
                )
            )
            continue
        if message.role == "assistant":
            blocks: list[str] = []
            group_id = f"chat-tool-group:{index}" if message.tool_calls else None
            for tool_call in message.tool_calls or []:
                function = tool_call.get("function", {})
                name = function.get("name", "")
                arguments = function.get("arguments", "")
                if not isinstance(arguments, str):
                    arguments = json.dumps(arguments, separators=(",", ":"), default=str)
                blocks.append(
                    f"<tool_use>\n<name>{name}</name>\n<arguments>{arguments}</arguments>\n</tool_use>"
                )
            if cleaned:
                blocks.append(f"Assistant: {cleaned}")
            if blocks:
                units.append(
                    PromptUnit(
                        text=PROMPT_SEPARATOR.join(blocks),
                        role=message.role,
                        group_id=group_id,
                    )
                )
            continue
        if message.role == "tool":
            tool_name = message.name or message.tool_call_id or "tool"
            group_id = tool_call_groups.get(str(message.tool_call_id or ""))
            if group_id is None:
                group_id = f"orphan-tool-group:{index}"
            units.append(
                PromptUnit(
                    text=f"<tool_result>\n<name>{tool_name}</name>\n<result>{cleaned}</result>\n</tool_result>",
                    role=message.role,
                    group_id=group_id,
                )
            )
            continue
        if cleaned:
            units.append(PromptUnit(text=f"{message.role.capitalize()}: {cleaned}", role=message.role))
    return units


def _joined_prompt_chars(texts: Sequence[str], separator: str) -> int:
    if not texts:
        return 0
    return sum(len(text) for text in texts) + len(separator) * (len(texts) - 1)


def _fit_prompt_to_budget(
    units: Sequence[PromptUnit],
    fixed_parts: Sequence[str] = (),
    max_chars: int | None = None,
    separator: str = PROMPT_SEPARATOR,
) -> str:
    budget_chars = PROMPT_BUDGET_CHARS if max_chars is None else int(max_chars)
    fixed_texts = [str(part) for part in fixed_parts if part]
    selected = list(units)
    dropped: set[tuple[str, Any]] = set()

    def unit_key(unit: PromptUnit) -> tuple[str, Any]:
        return ("group", unit.group_id) if unit.group_id is not None else ("unit", id(unit))

    def render(current: Sequence[PromptUnit]) -> str:
        return separator.join([*fixed_texts, *(unit.text for unit in current if unit.text)])

    full_prompt = render(selected)
    if len(full_prompt) <= budget_chars:
        return full_prompt

    for unit in selected:
        if not unit.optional or unit.protected:
            continue
        key = unit_key(unit)
        if key in dropped:
            continue
        dropped.add(key)
        remaining = [candidate for candidate in selected if unit_key(candidate) not in dropped]
        prompt = render(remaining)
        if len(prompt) <= budget_chars:
            return prompt

    remaining = [candidate for candidate in selected if unit_key(candidate) not in dropped]
    required_chars = _joined_prompt_chars(
        [*fixed_texts, *(candidate.text for candidate in remaining if candidate.text)],
        separator,
    )
    raise PromptBudgetExceeded(required_chars, budget_chars)


def _prompt_budget_http_response(error: PromptBudgetExceeded) -> JSONResponse:
    return JSONResponse(
        status_code=413,
        content={
            "error": {
                "message": str(error),
                "type": "context_length_exceeded",
                "code": "context_length_exceeded",
            }
        },
    )


def _prompt_budget_ws_error(error: PromptBudgetExceeded) -> dict[str, Any]:
    return {
        "type": "error",
        "error": {
            "message": str(error),
            "type": "context_length_exceeded",
            "code": "context_length_exceeded",
        },
    }


