function parseAttributes(raw) {
  const attributes = {};
  const pattern = /([^\s=/>]+)(?:\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s"'=<>`]+)))?/g;
  for (const match of raw.matchAll(pattern)) {
    attributes[match[1].toLowerCase()] = match[2] ?? match[3] ?? match[4] ?? '';
  }
  return attributes;
}

function elements(html, tagName) {
  const pattern = new RegExp(`<\\s*${tagName}\\b([^>]*?)\\/?\\s*>`, 'gi');
  return Array.from(html.matchAll(pattern), (match) => parseAttributes(match[1]));
}

function attr(element, name) {
  return element[name.toLowerCase()];
}

function checkFallback(html, label) {
  const definitions = [
    ['title', null, 'title', null],
    ['meta', 'name', 'description', 'content'],
    ['link', 'rel', 'canonical', 'href'],
    ['meta', 'property', 'og:title', 'content'],
    ['meta', 'property', 'og:description', 'content'],
    ['meta', 'property', 'og:url', 'content'],
    ['meta', 'property', 'og:type', 'content'],
    ['meta', 'property', 'og:image', 'content'],
  ];
  for (const [tag, selectorName, selectorValue, contentName] of definitions) {
    const matches = elements(html, tag).filter((element) => attr(element, selectorName) === selectorValue);
    check(`${label} has one ${selectorValue ?? tag}`, matches.length === 1, `expected exactly one ${selectorValue ?? tag}`);
    if (matches.length === 1 && selectorValue && ['title', 'description', 'canonical', 'og:title', 'og:description', 'og:url', 'og:type', 'og:image'].includes(selectorValue)) {
      check(`${label} ${selectorValue} has data-rh ownership`, attr(matches[0], 'data-rh') === 'true', `${selectorValue} is not managed by Helmet`);
    }
    if (matches.length === 1 && contentName) {
      check(`${label} ${selectorValue} has content`, typeof attr(matches[0], contentName) === 'string', `${selectorValue} has no content`);
    }
  }
}

