def asset_checks():
    targets = [
        ('bbt', BBT_PORT, BBT_MANIFEST_NAME, 'manifest'),
        ('bbt', BBT_PORT, BBT_APPLE_NAME, 'new_apple'),
        ('bbt', BBT_PORT, 'logo.png', 'image'),
        ('bbt', BBT_PORT, 'og-cover.png', 'image'),
        ('bbt', BBT_PORT, 'products/index.html', 'html'),
        ('ait', AIT_PORT, 'favicon-16x16.png', 'image'),
        ('ait', AIT_PORT, 'favicon-32x32.png', 'image'),
        ('ait', AIT_PORT, 'og-image.png', 'image'),
    ]
    result = []
    for site, port, path, kind in targets:
        with urllib.request.urlopen(f'http://127.0.0.1:{port}/{path}', timeout=10) as response:
            body = response.read()
            item = {'site': site, 'path': path, 'status': response.status, 'bytes': len(body), 'content_type': response.headers.get('Content-Type', ''), 'sha256': hashlib.sha256(body).hexdigest()}
        if kind == 'new_apple':
            item['valid_magic'] = body.startswith(b'\x89PNG')
            item['dimensions'] = {'width': int.from_bytes(body[16:20], 'big'), 'height': int.from_bytes(body[20:24], 'big')}
            item['pass'] = item['status'] == 200 and item['content_type'] == 'image/png' and item['sha256'] == BBT_APPLE_SHA256 and item['dimensions'] == {'width': 180, 'height': 180}
        elif kind == 'manifest':
            item['valid_json'] = isinstance(json.loads(body), dict)
            item['icon_source'] = json.loads(body).get('icons', [])[-1].get('src') if item['valid_json'] else None
            item['pass'] = item['status'] == 200 and item['content_type'] == 'application/manifest+json' and item['sha256'] == BBT_MANIFEST_SHA256 and item['icon_source'] == '/' + BBT_APPLE_NAME
        elif kind == 'image':
            item['valid_magic'] = body.startswith((b'\x89PNG', b'\xff\xd8', b'GIF8', b'RIFF', b'\x00\x00\x01\x00'))
            item['pass'] = item['status'] == 200 and item['valid_magic']
        else:
            item['contains_whatsedit'] = b'WhatsEdit' in body and b'whatsedit.aitshirts.in' in body
            item['pass'] = item['status'] == 200 and item['contains_whatsedit']
        result.append(item)
    return result

