  console.log('  ✓ an idle WebChat controller releases its broker lease after one operation');
}

async function testWebLeaseWaitsForLastOverlappingOperation() {
  let releases = 0;
  const blockers = [];
  const controller = new WebChatBrowserController({
    lease: { release: async () => { releases += 1; } }
  });
  controller.askOnce = async key => {
    await new Promise(resolve => blockers.push(resolve));
    return `${key}:done`;
  };
  const first = controller.ask('glm-5.3', 'A');
  const second = controller.ask('qwen3.8-max', 'B');
  await sleep(20);
  assert.strictEqual(releases, 0);
  blockers.shift()();
  await first;
  assert.strictEqual(releases, 0);
  blockers.shift()();
  await second;
  assert.strictEqual(releases, 1);
  console.log('  ✓ overlapping browser calls release one shared lease only after the last call');
}

