async function testDiscussionDeadlineStopsNewPhases() {
  console.log('\nResilience: discussion deadline stops new phases');
  const council = makeCouncil({ discussionTimeoutMs: 20, maxSatisfactionLoops: 2 });
  let calls = 0;
  council.askModel = async () => {
    calls += 1;
    await new Promise(resolve => setTimeout(resolve, 35));
    return 'usable analysis';
  };
  const discussion = await council.discuss('p', 'c', { models: ['glm-latest'], maxRounds: 1 });
  assert.strictEqual(calls, 1, 'no new round should start after the deadline');
  assert.strictEqual(discussion.deadlineExceeded, true, 'deadline marker must be present');
  assert.strictEqual(discussion.rounds.length, 1, 'only the completed initial phase should remain');
  await council.close();
  console.log('  ✓ deadline returns the completed phase instead of starting more work');
}

async function testSatisfactionLoopIsBounded() {
  console.log('\nResilience: satisfaction loop is bounded');
  const council = makeCouncil({ maxSatisfactionLoops: 1 });
  council.askModel = async () => 'usable plan';
  council.askForPlanReview = async () => 'NOT SATISFIED: revise this plan';
  const discussion = await council.discuss('p', 'c', { models: ['glm-latest'], maxRounds: 0 });
  assert.strictEqual(discussion.satisfactionLoop.filter(item => item.reviews).length, 1);
  assert.strictEqual(discussion.satisfactionLoop.some(item => item.verdict === 'MAX_LOOPS_REACHED'), true);
  await council.close();
  console.log('  ✓ satisfaction loop stops at the configured limit');
}

