async ask(prompt, systemInstruction = null, temperature = 0.7) {
  const maxAttempts = this.maxAttempts;
  let lastError = null;
  let lastWasQueueShed = false;
  for (let attempt = 1; attempt <= maxAttempts; attempt++) {
    try {
      return await this._askOnce(prompt, systemInstruction, temperature);
    } catch (err) {
      lastError = err;
      lastWasQueueShed = /queue_shed|queue full/i.test(err.message);
      console.error(`[CopilotClient] attempt ${attempt}/${maxAttempts} failed: ${err.message}`);
      if (attempt < maxAttempts && !lastWasQueueShed) {
        await new Promise(resolve => setTimeout(resolve, 1500 * attempt));
      }
    }
  }
  const detail = lastWasQueueShed
    ? 'backend queue unavailable; skipped without another retry'
    : 'the M365 Copilot backend keeps returning filler text — restart it with: ssh oracle-vps \'sudo systemctl restart copilot-proxy\'';
  throw new Error(`${lastError ? lastError.message : 'unknown error'} (after ${lastWasQueueShed ? 1 : maxAttempts} attempts; ${detail})`);
}

