def validate_evidence_bundle(bundle, events):
    errors = []
    events = tuple(events)
    heads = {}
    event_ids = {item.event_id for item in events}
    for event in events:
        heads[event.lead_id] = event.event_hash
    if bundle.event_head_hashes != tuple(sorted(heads.values())):
        errors.append("event head mismatch")
    for record in bundle.records:
        if record.event_id not in event_ids:
            errors.append("orphan evidence event")
        matching = next((item for item in events if item.event_id == record.event_id), None)
        if matching is None or matching.event_hash != record.event_head_hash:
            errors.append("evidence event hash mismatch")
    return tuple(sorted(set(errors)))

