def _find_tag_start(source: str, gt_index: int) -> int:
    """Index of the '<' that opens the tag whose '>' sits at ``gt_index``."""
    index = gt_index - 1
    while index >= 0:
        char = source[index]
        if char in "\"'`":
            quote = char
            index -= 1
            while index >= 0:
                if source[index] == quote:
                    break
                index -= 1
            index -= 1
            continue
        if char == "<":
            return index
        index -= 1
    return -1


def _tag_ends_at(source: str, gt_index: int) -> tuple[str, bool, int] | None:
    lt = _find_tag_start(source, gt_index)
    if lt < 0:
        return None
    closing = source.startswith("</", lt)
    name_start = lt + (2 if closing else 1)
    match = _IDENT.match(source, name_start)
    if match is None:
        return None
    return match.group(0), closing, lt


def _inner_text_of_matching_open(source: str, close_lt: int, name: str) -> str:
    """Text between the matching ``<name ...>`` and ``</name>`` before close_lt."""
    open_pattern = re.compile(rf"<(?!/){re.escape(name)}\b")
    close_pattern = re.compile(rf"</{re.escape(name)}\s*>")
    depth = 1
    cursor = close_lt - 1
    while cursor >= 0 and depth > 0:
        nearest_open = None
        nearest_close = None
        for match in open_pattern.finditer(source, 0, cursor):
            nearest_open = match.start()
        for match in close_pattern.finditer(source, 0, cursor):
            nearest_close = match.start()
        if nearest_close is None and nearest_open is None:
            return ""
        if nearest_close is not None and (
            nearest_open is None or nearest_close > nearest_open
        ):
            depth += 1
            cursor = nearest_close
            continue
        depth -= 1
        if depth == 0:
            gt = source.find(">", nearest_open)
            if gt == -1 or gt > close_lt:
                return ""
            return source[gt + 1 : close_lt]
        cursor = nearest_open
    return ""


def backwards_label(source: str, position: int, lookback: int = MAX_LABEL_LOOKBACK) -> str:
    """Find the nearest plausible visible label text preceding ``position``.

    Walks backwards across tag boundaries rather than relying on brace depth,
    so it correctly reads JSX text nested inside component function bodies
    (which are themselves wrapped in braces). Sibling elements are walked in
    order, so a unit suffix such as ``{value}px`` is skipped in favour of the
    real label in the preceding sibling.
    """
    window_start = max(0, position - lookback)
    cursor = position - 1

    for _ in range(MAX_LABEL_STEPS):
        while cursor >= window_start and source[cursor].isspace():
            cursor -= 1
        if cursor < window_start or source[cursor] != ">":
            return ""

        parsed = _tag_ends_at(source, cursor)
        if parsed is None:
            return ""
        name, closing, lt = parsed

        if closing and name in LABEL_ELEMENTS:
            candidate = clean_text_run(
                _inner_text_of_matching_open(source, lt, name)
            )
            if not is_noise_text(candidate):
                return candidate

        cursor = lt - 1

    return ""

