def _find_node(xml: str, needle: str, exact: bool = True) -> tuple[int, int] | None:
    """Match a node by its text/content-desc value, unescaping entities first.

    The UI dump encodes emoji as numeric entities (&#128187;) and quotes
    as &amp;/&quot;, while node_values() unescapes them - so titles pulled
    from node_values() never match the raw XML unless we unescape here.
    Substring matching stays case-sensitive so "Submit" cannot hit the
    heading "You're about to submit a report".
    """
    for match in re.finditer(r'<(?:node|view)[^>]*?(?:text|content-desc)="([^"]*)"[^>]*bounds="\[(\d+),(\d+)\]\[(\d+),(\d+)\]"', xml):
        value = html.unescape(match.group(1))
        if (value == needle) if exact else (needle in value):
            x1, y1, x2, y2 = map(int, match.groups()[1:])
            return (x1 + x2) // 2, (y1 + y2) // 2
    return None


def _find_exact(xml: str, needle: str) -> tuple[int, int] | None:
    return _find_node(xml, needle, exact=True)


