def prune(
    keep: int = DEFAULT_KEEP,
    max_bytes: int = DEFAULT_MAX_BYTES,
    receipt_keep: int = DEFAULT_RECEIPT_KEEP,
) -> dict:
    """Enforce retention.

    Contract:
      * at most ``keep`` cycle directories survive with full media;
      * cycle JSON receipts survive far longer (``receipt_keep``) because they
        are a few KB each and are the durable audit trail;
      * under size pressure, heavy media is stripped from *clean* cycles
        oldest-first, so any cycle that found something keeps its evidence;
      * only if that is not enough are the oldest cycle directories removed.
    """
    cycles = sorted(
        (path for path in config.ARTIFACT_DIR.glob("cycle-*") if path.is_dir()),
        key=_cycle_sort_key,
    )
    removed: list[str] = []
    stripped: list[str] = []
    freed = 0

    # 1. Age: anything beyond the retention window is deleted outright.
    for path in cycles[: max(0, len(cycles) - keep)]:
        freed += _dir_bytes(path)
        shutil.rmtree(path, ignore_errors=True)
        removed.append(path.name)

    # 2. Size pressure: strip heavy media from clean cycles, oldest-first.
    remaining = sorted(
        (path for path in config.ARTIFACT_DIR.glob("cycle-*") if path.is_dir()),
        key=_cycle_sort_key,
    )
    total = sum(_dir_bytes(path) for path in remaining)
    for path in remaining:
        if total <= max_bytes:
            break
        if not _is_clean(path):
            continue
        reclaimed = _strip_media(path)
        if reclaimed:
            freed += reclaimed
            total -= reclaimed
            stripped.append(path.name)

    # 3. Still over budget: remove oldest cycle directories. Receipts stay.
    if total > max_bytes:
        remaining = sorted(
            (path for path in config.ARTIFACT_DIR.glob("cycle-*") if path.is_dir()),
            key=_cycle_sort_key,
        )
        for path in remaining:
            if total <= max_bytes:
                break
            size = _dir_bytes(path)
            shutil.rmtree(path, ignore_errors=True)
            freed += size
            total -= size
            removed.append(path.name)

    # 4. Age out receipts, which are tiny but still bounded.
    receipts = sorted(
        config.ARTIFACT_DIR.glob("cycle-*.json"), key=lambda p: _cycle_sort_key(p.with_suffix(""))
    )
    dropped_receipts: list[str] = []
    for receipt in receipts[: max(0, len(receipts) - receipt_keep)]:
        try:
            freed += receipt.stat().st_size
            receipt.unlink()
            dropped_receipts.append(receipt.name)
        except OSError:
            continue

    return {
        "removed": removed,
        "stripped_media": stripped,
        "dropped_receipts": dropped_receipts,
        "freed_bytes": freed,
        "freed_mb": round(freed / 1e6, 1),
        "remaining_cycles": len(
            [p for p in config.ARTIFACT_DIR.glob("cycle-*") if p.is_dir()]
        ),
        "remaining_receipts": len(list(config.ARTIFACT_DIR.glob("cycle-*.json"))),
        "remaining_bytes": sum(
            _dir_bytes(path)
            for path in config.ARTIFACT_DIR.glob("cycle-*")
            if path.is_dir()
        ),
    }

