def _summarise_findings(findings: list[dict]) -> dict:
    auto: list[dict] = []
    report_only: list[dict] = []
    for finding in findings:
        if finding["code"] in config.AUTO_FIXABLE_CODES:
            auto.append(finding)
        else:
            report_only.append(finding)
    return {"auto_fixable": auto, "report_only": report_only}

