def _match_option(field: dict, value: str) -> str:
    """Pick a select/radio option value or text that matches `value`.

    Accepts BOTH option shapes, because the producer and the consumer disagreed:
    the DOM extractor emits plain strings (`options=[o.get('text') for o in
    ...]`) while this function used to assume dicts and call `o.get('text')`.
    Every select and radio question therefore raised
    `AttributeError: 'str' object has no attribute 'get'`, which aborted the
    deterministic mapper for that form. Options now arrive as strings from the
    extractor and as dicts from some callers, so both are normalised here.
    """
    v = str(value)
    if not v:
        return None

    def _text(o):
        if isinstance(o, dict):
            return str(o.get('text') or o.get('label') or o.get('name') or '').strip()
        return str(o or '').strip()

    def _val(o):
        if isinstance(o, dict):
            return str(o.get('value') or o.get('text') or '').strip()
        return str(o or '').strip()

    options = list(field.get('options') or [])

    for o in options:
        ot, ov = _text(o), _val(o)
        if ot.lower() == v.lower() or (ov and ov.lower() == v.lower()):
            return ot or ov
    for o in options:
        ot = _text(o).lower()
        if ot and (v.lower() in ot or ot in v.lower()):
            return _val(o) or _text(o)
    return None

