async def _resolve_field_handle(page, f, stale_handle):
    """Return a FRESH handle for field `f` from the current DOM.

    Guards against index drift: the LLM takes seconds to answer, and if the
    page re-renders in between, the stale handle can point at a DIFFERENT
    field — which is how values end up in the wrong input. Re-resolve by
    matching the field's label (or name attribute) against the live form.
    Falls back to the stale handle if no fresh match is found.
    """
    if f.get('tag') == 'group':
        return stale_handle
    label = f.get('label') or ''
    name = f.get('name') or ''
    if not label and not name:
        return stale_handle
    try:
        for el in await page.query_selector_all('input:not([type="hidden"]), select, textarea'):
            try:
                if not await el.is_visible():
                    continue
                if label:
                    l2 = (await _get_label_for_input(page, el)).strip()
                    if l2 and (l2 == label or (label in l2) or (l2 in label)):
                        return el
                if name:
                    n2 = (await el.get_attribute('name') or '').strip()
                    if n2 == name:
                        return el
            except Exception:
                continue
    except Exception:
        pass

