class LiteLLMEnhancer:
    """Single OpenAI-compatible call against the VPS LiteLLM proxy.

    Kept for a one-shot request. :class:`ChainEnhancer` is what the pipeline uses,
    because one ``auto`` request fails often enough to matter.
    """

    def __init__(
        self,
        base_url: str | None = None,
        api_key: str | None = None,
        model: str | None = None,
        timeout: int | None = None,
    ):
        self.base_url = (base_url or os.getenv("BLOG_LLM_BASE", "http://127.0.0.1:4000/v1")).rstrip("/")
        self.api_key = api_key or os.getenv("BLOG_LLM_KEY", "sk-litellm-vps-2026")
        self.model = model or os.getenv("BLOG_LLM_MODEL", "auto")
        # max_tokens must exceed the thinking budget or content comes back empty.
        self.timeout = timeout or int(os.getenv("BLOG_LLM_TIMEOUT", "240"))
        self.max_tokens = int(os.getenv("BLOG_LLM_MAX_TOKENS", "16000"))

    def call(self, prompt: str) -> tuple[str, str, str]:
        """Return ``(content, finish_reason, routed_model)``. Never raises."""
        body = json.dumps(
            {
                "model": self.model,
                "messages": [
                    {"role": "system", "content": "You are a senior engineer writing a real "
                                                      "postmortem-style retrospective. You output "
                                                      "only raw HTML."},
                    {"role": "user", "content": prompt},
                ],
                "temperature": 0.75,
                "max_tokens": self.max_tokens,
            }
        ).encode("utf-8")
        req = urllib.request.Request(
            f"{self.base_url}/chat/completions",
            data=body,
            headers={
                "Content-Type": "application/json",
                "Authorization": f"Bearer {self.api_key}",
                "User-Agent": "oc-blog-pipeline/1.0",
            },
        )
        try:
            with urllib.request.urlopen(req, timeout=self.timeout) as resp:
                data = json.loads(resp.read().decode("utf-8", "replace"))
        except Exception:
            return "", "error", ""
        try:
            message = data["choices"][0]["message"]
            return (message.get("content") or "",
                    data["choices"][0].get("finish_reason") or "",
                    str(data.get("model") or ""))
        except (KeyError, IndexError, TypeError):
            return "", "error", ""

    def enhance(self, prompt: str) -> str:
        return self.call(prompt)[0]


class ChainEnhancer:
    """Walks the model chain until one returns a valid article (B1).

    Every attempt is recorded - model, routed model, elapsed, output size, finish
    reason, and *why* it was rejected. The rejection reason was previously
    discarded, which is what made a 50% failure rate invisible.
    """

    def __init__(
        self,
        chain: list[str] | None = None,
        timeout: int = 180,
        max_tokens: int = 16000,
        client: LiteLLMEnhancer | None = None,
        transport=None,
    ):
        self.chain = list(chain) if chain else load_auto_chain(
            override=os.getenv("BLOG_LLM_CHAIN"))
        self.timeout = timeout
        self.max_tokens = max_tokens
        self.client = client or LiteLLMEnhancer(timeout=timeout, max_tokens=max_tokens)
        self._transport = transport
        self._attempts: list[dict[str, Any]] = []

    @property
    def attempts(self) -> list[dict[str, Any]]:
        return list(self._attempts)

    def _call(self, model: str, prompt: str) -> tuple[str, str, str]:
        if self._transport is not None:
            return self._transport(model, prompt, self.timeout, self.max_tokens)
        return self.client.call(prompt) if model == self.client.model else self._call_named(model, prompt)

    def _call_named(self, model: str, prompt: str) -> tuple[str, str, str]:
        client = LiteLLMEnhancer(timeout=self.timeout, max_tokens=self.max_tokens)
        client.model = model
        return client.call(prompt)

    def enhance(self, prompt: str) -> str:
        self._attempts = []
        writer = BlogWriter()
        for model in self.chain:
            started = time.monotonic()
            try:
                content, finish, routed = self._call(model, prompt)
            except Exception as exc:  # noqa: BLE001 - one bad link must not stop the chain
                self._attempts.append(_attempt_record(
                    model, "", "", 0, 0, "error",
                    f"{type(exc).__name__}: {exc}", time.monotonic() - started))
                continue

            html = BlogWriter._extract_article(content or "")
            if html is None:
                reason = "empty" if not (content or "").strip() else "no_article"
            else:
                reason = writer.validate(html) or "ok"
            self._attempts.append(_attempt_record(
                model, content or "", finish or "", routed or "",
                len(content or ""), reason, time.monotonic() - started))
            if reason == "ok":
                return html
        return ""


def _attempt_record(model, _content, finish, routed, size, reason, elapsed) -> dict[str, Any]:
    return {
        "ts": datetime.now(timezone.utc).isoformat(timespec="seconds"),
        "model": model,
        "routed_model": routed or "",
        "finish_reason": finish or "",
        "output_bytes": int(size),
        "elapsed_ms": int(elapsed * 1000),
        "reason": reason or "unknown",
    }

