/**
 * Keep the host's MCP tool timeout alive during long council runs.
 * opencode calls callTool with resetTimeoutOnProgress + a progressToken;
 * a matching notifications/progress resets its timer, so a 20-minute
 * discussion is not killed by a 60s/30min host budget while it works.
 * No-op when the client sent no progressToken.
 */
_startProgressHeartbeat(progressToken) {
  if (progressToken === undefined || progressToken === null) return () => {};
  let ticks = 0;
  const timer = setInterval(() => {
    ticks += 1;
    try {
      const pending = this.server.sendNotification({
        method: 'notifications/progress',
        params: { progressToken, progress: ticks }
      });
      if (pending && typeof pending.catch === 'function') pending.catch(() => {});
    } catch (err) {
      // transport already closed; nothing to reset
    }
  }, 15000);
  if (typeof timer.unref === 'function') timer.unref();
  return () => clearInterval(timer);
}

