    """Judge in two stages, split by FUNCTION rather than by call count.

    Stage 1 sees ONLY the attributed evidence — a few dozen dated units, which
    are the only ones that can justify a span. Stage 2 runs on the unattributed
    narrative ONLY IF stage 1 found no primary dated unit.

    This is not latency theatre. Given one mixed list of ~38 units the judge
    stopped connecting "managed 50+ servers" to technical support and picked
    undated filler instead; given the ~30 attributed units alone it makes the
    connection immediately. Stage 2 is skipped in the common case, so the extra
    call is not on the critical path for most questions.
    """
    call = llm_call
    if call is None:
        try:
            from llm_router import call_llm_fast
            call = call_llm_fast
        except Exception:
            return {"error": "no_llm", "selected": [], "rejected": [], "adjacent_ids": []}

    attributed = [u for u in evidence if u.has_dates()]
    unattributed = [u for u in evidence if not u.has_dates()]
    empty = {"error": None, "selected": [], "rejected": [], "adjacent_ids": []}

