            return dict(empty)
        prompt = _JUDGE_PROMPT.format(
            question=question, capability=capability)
        prompt += ("\nATTRIBUTED EVIDENCE (employer and dates — these alone can "
                   "justify a span):\n" if any(u.has_dates() for u in units) else "")
        prompt += ("\nEVIDENCE:\n" + _fmt(units))
        if adj:
            prompt += ("\n\nADJACENT (transferable, NOT the asked capability) "
                       "candidates:\n" + _fmt(adj))
        try:
            res = call([{"role": "user", "content": prompt}],
                       temperature=0.0, max_tokens=1600, timeout=60)
        except Exception as exc:
            return {"error": f"llm_failed: {exc}", "selected": [],
                    "rejected": [], "adjacent_ids": []}
        return _validate(_parse_json(_content_of(res)), units, adj)

    stage1 = _run(attributed, [])
    if stage1.get("error"):
        return stage1

    # Stage 1 suffices if it produced any dated primary selection.
    got_dated_primary = any(
        s["unit"].has_dates() and s["relation"] == "primary"
        for s in stage1["selected"])
    if got_dated_primary or not unattributed:
        stage1["adjacent_pool_used"] = []
        return stage1

    stage2 = _run(unattributed, adjacency)
    if stage2.get("error"):
        stage1["adjacent_pool_used"] = [u.uid for u in adjacency]
        return stage1
    # Prefer stage 1 (dated) selections; stage 2 only adds corroboration and the
    # adjacent pool. Its undated primaries can never contribute a span anyway.
    stage1["selected"] = stage1["selected"] + [
        s for s in stage2["selected"] if s["relation"] != "primary"]
    stage1["rejected"] += stage2["rejected"]
    stage1["adjacent_ids"] = stage2["adjacent_ids"]
    stage1["adjacent_pool_used"] = [u.uid for u in adjacency]
    return stage1


