        q = _norm_for_quote(quote)
        if len(q.split()) < 4 or q not in _norm_for_quote(unit.text):
            rejected.append({"id": uid, "why": "quote_not_in_unit"})
            continue
        rel = str(sel.get("relation") or "").strip().lower()
        if rel not in ("primary", "incidental", "adjacent"):
