def level_for_db(weighted_db, current_level=DEFAULT_VOLUME_LEVEL):
  """Map a mic dB reading onto one of the discrete volume levels.

  Hysteresis keeps the level put until the reading is a full band past the boundary,
  so a reading hovering on a step edge does not make the prompts jump.
  """
  step = DB_SCALE / MAX_VOLUME_LEVEL
  raw = (float(weighted_db) - AMBIENT_DB) / step
  level = min(max(math.floor(raw + 0.5), 0), MAX_VOLUME_LEVEL)
  if level != current_level and abs(raw - current_level) < VOLUME_HYSTERESIS_DB / step:
    return min(max(int(current_level), 0), MAX_VOLUME_LEVEL)
  return level


def volume_for_level(level):
  return float(VOLUME_LEVELS[min(max(int(level), 0), MAX_VOLUME_LEVEL)])


def calculate_volume(weighted_db, current_level=DEFAULT_VOLUME_LEVEL):
  return volume_for_level(level_for_db(weighted_db, current_level))

