/**
 * Run the configured mechanical check once. A non-zero exit or an explicit
 * failure signature in the output becomes a TOOL_CONFIRMED ledger blocker,
 * which review loops cannot dismiss as an opinion.
 */
async runMechanicalCheck() {
  if (!this.mechanicalCheck) {
    return { output: '', blocker: null, summary: 'mechanical check not configured' };
  }
  const started = Date.now();
  const result = await new Promise((resolve) => {
    let child;
    try {
      child = spawn(this.mechanicalCheck, { shell: true, cwd: process.cwd() });
    } catch (err) {
      resolve({ ok: false, code: null, output: String(err.message) });
      return;
    }
    let out = '';
    let settled = false;
    const finish = (value) => {
      if (settled) return;
      settled = true;
      clearTimeout(timer);
      resolve(value);
    };
    const timer = setTimeout(() => {
      try { child.kill('SIGKILL'); } catch (err) { /* already gone */ }
      finish({ ok: false, code: null, output: `${out}\n[mechanical check exceeded ${this.mechanicalTimeoutMs}ms]` });
    }, this.mechanicalTimeoutMs);
    const collect = (chunk) => { out += chunk.toString(); };
    child.stdout.on('data', collect);
    child.stderr.on('data', collect);
    child.on('error', (err) => finish({ ok: false, code: null, output: `${out}\n${err.message}` }));
    child.on('close', (code) => finish({ ok: code === 0, code, output: out }));
  });

  const output = String(result.output || '').trim().slice(-4000);
  const failureSignature = /\b(fail(?:ing|ed|ures?|ure)?|error|errors|traceback|assertionerror|not ok)\b|\u2717|\u2716/i;
  const failed = result.ok !== true || failureSignature.test(output);
  const tail = output.split('\n').filter(Boolean).slice(-3).join(' ').slice(0, 300);
  const blocker = failed ? {
    id: 'mechanical:M1',
    model: 'mechanical',
    localId: 'M1',
    severity: 'HIGH',
    status: 'TOOL_CONFIRMED',
    target: `command: ${this.mechanicalCheck}`,
    defect: `mechanical check did not pass: ${tail || `exit code ${result.code}`}`,
    evidence: output.slice(-800),
    proposedFix: 'Fix the mechanical failure, or state explicitly in the plan why it is acceptable',
    source: 'mechanical',
    resolved: false
  } : null;

  this.telemetry.mechanical = {
    command: this.mechanicalCheck,
    exitCode: result.code,
    failed,
    durationMs: Date.now() - started,
    blocker
  };
  console.error(`[Council] mechanical check: ${this.mechanicalCheck} → exit ${result.code}${failed ? ' (FAILED)' : ''} in ${Date.now() - started}ms`);
  return {
    output,
    blocker,
    summary: `${this.mechanicalCheck} → exit ${result.code}${failed ? ' (failed)' : ''}`
  };
}

/** Pick the auditor: prefer a healthy seat that did not write the plan. */
_pickAuditor(healthyModels, allModels) {
  const healthy = healthyModels.filter(Boolean);
  if (healthy.length === 0) return null;
  const revisor = this.telemetry.revisor;
  const withoutRevisor = healthy.filter(m => m !== revisor);
  const pool = withoutRevisor.length ? withoutRevisor : healthy;
  return pool[pool.length - 1];
}

async runFreshReview({ problem, plan, ledgerBlockers = [], healthyModels = [], allModels = [], roundZero = [], labels = null }) {
  const auditor = this._pickAuditor(healthyModels, allModels);
  if (!auditor) return null;
  this.telemetry.auditModel = auditor;
  const prompt = ledger.buildAuditPrompt({
    model: auditor,
    problem,
    plan,
    ledgerSummary: ledger.summarizeLedger(ledgerBlockers),
    roundZero: labels ? ledger.anonymizePeerResponses(roundZero, labels) : ''
  });
  const seat = await this.askSeat(auditor, prompt);
  if (seat.error) {
    console.error(`[Council] audit unusable for ${auditor}: ${String(seat.text).substring(0, 200)}`);
    return { model: auditor, error: true, verdict: null, missed: [], dissent: null };
  }
  const parsed = ledger.parseAuditResult(seat.text);
  console.error(`[Council] audit by ${auditor}: ${parsed.verdict} (${parsed.missed.length} missed issue(s))`);
  return { model: auditor, verdict: parsed.verdict, missed: parsed.missed, dissent: parsed.dissent };
}

