function parseDissent(text) {
  const match = String(text || '').match(/^\s*DISSENT\s*[:=]\s*([\s\S]*)$/im);
  if (!match) return null;
  const value = match[1].trim();
  if (!value || /^(none|n\/a|nil|-|no dissent)\b/i.test(value)) return null;
  return value;
}

/**
 * The fresh auditor answers with AUDIT: PASS | PLAN INCOMPLETE | PLAN UNSOUND
 * plus a MISSED: list. Anything it flags is attributed to `audit` so the ledger
 * can tell a deliberating seat's opinion from an independent finding.
 */
function parseAuditResult(text) {
  const raw = typeof text === 'string' ? text : String(text || '');
  const verdictMatch = raw.match(/^\s*AUDIT\s*[:=]\s*(.+)$/im);
  if (!verdictMatch) {
    return { verdict: null, missed: [], dissent: null, structured: false };
  }
  const head = verdictMatch[1].toUpperCase();
  const verdict = /INCOMPLETE/.test(head) ? 'PLAN_INCOMPLETE' : (/UNSOUND/.test(head) ? 'PLAN_UNSOUND' : 'PASS');
  const missedMatch = raw.match(/^\s*MISSED\s*[:=]\s*([\s\S]*?)(?=^\s*DISSENT\s*[:=]|$)/im);
  const missed = (missedMatch ? parseBlockerLines(missedMatch[1]) : []).map(b => ({
    ...b,
    id: `audit:${b.localId}`,
    source: 'audit',
    resolved: false,
    // An auditor that lists an issue is reporting it as unaddressed.
    status: b.status === 'RESOLVED' ? 'OPEN' : b.status
  }));
  return { verdict, missed, dissent: parseDissent(raw), structured: true };
}

