class TestAuthFailureBucket:
    """401/403, or unmistakable auth body."""

    def test_401(self):
        assert p.classify_error(401, "Invalid API key") == p.AUTH_FAILURE

    def test_403(self):
        assert p.classify_error(403, "Forbidden") == p.AUTH_FAILURE

    def test_invalid_key_body(self):
        assert p.classify_error(200, "unauthorized: invalid key") == p.AUTH_FAILURE

    def test_revoked_key(self):
        assert p.classify_error(200, "revoked API key") == p.AUTH_FAILURE

    def test_daily_quota_not_override(self):
        # "insufficient credits" is a daily/quota signal, so daily_quota wins
        assert p.classify_error(401, "insufficient credits") == p.DAILY_QUOTA

    def test_429_with_invalid_key(self):
        # 429 has precedence over auth body, so transient_rate_limit wins
        assert p.classify_error(429, "invalid api key") == p.TRANSIENT_RATE_LIMIT

    def test_403_with_insufficient_credits(self):
        # 403 is auth status, but "insufficient credits" is daily. Auth wins because status precedes body?
        # The precedence order: daily (body) -> transient (code=429) -> auth (status or body) -> server -> unknown
        # So 403 with daily body: status is auth, and auth > unknown, but daily > auth? daily already failed, so auth wins.
        # However, status is 403 -> auth_failure.
        assert p.classify_error(403, "insufficient credits") == p.AUTH_FAILURE

