def apply_date_range(page, after_ddmmyyyy: str, before_ddmmyyyy: str, timeout: int = 40) -> bool:
    """Apply a custom date range through the real filter dialog.

    Measured requirements this works around:
      * URL ?min=&max= params are IGNORED on a fresh navigation.
      * The date inputs have NO stable id — across two loads they were #c3/#c9 and
        then #c2/#c8. They are located POSITIONALLY: the visible text inputs,
        excluding the MyActivity search box.
      * A plain .value assignment does not update the control's model, so the
        native value setter is used.
      * Apply is clicked by exact text match and never if it matches /delete/i.
    """
    import time as _t
    ok = page.evaluate(
        """([after, before]) => {
      const setNative = (el, v) => {
        Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, 'value')
          .set.call(el, v);
        el.dispatchEvent(new Event('input', {bubbles: true}));
        el.dispatchEvent(new Event('change', {bubbles: true}));
      };
      document.querySelectorAll('div,button,span').forEach(e => {
        const t = (e.textContent || '').trim();
        if ((t === 'Got it' || t === 'Dismiss') && t.length < 12) { try { e.click(); } catch(_){} }
      });
      const btn = document.querySelector('button[aria-label="Filter by date & product"]');
      if (!btn) return 'no-filter-button';
      btn.dispatchEvent(new MouseEvent('click', {bubbles: true, cancelable: true, view: window}));

      const visibleTextInputs = () => [...document.querySelectorAll('input[type=text]')]
        .filter(i => i.offsetParent
                     && !/search box/i.test(i.getAttribute('aria-label') || '')
                     && !/myactivity/i.test(i.value || ''));

      // the Custom range fields only exist once "Custom" is chosen
      const custom = [...document.querySelectorAll('div,span,label')]
        .filter(e => /^\\s*Custom\\s*$/.test(e.textContent || ''));
      if (custom.length) { try { custom[custom.length - 1].click(); } catch(_){} }

      const fields = visibleTextInputs();
      if (fields.length < 2) return 'date-inputs-missing:' + fields.length;
      setNative(fields[0], after);
      setNative(fields[1], before);

      const apply = [...document.querySelectorAll('div,button,span')]
        .filter(e => /^\\s*Apply\\s*$/.test(e.textContent || ''));
      const el = apply[apply.length - 1];
      if (!el) return 'no-apply';
      if (/delete/i.test(el.textContent || '')) return 'refused-delete';
      el.dispatchEvent(new MouseEvent('click', {bubbles: true, cancelable: true, view: window}));
      return 'ok';
    }""",
        [after_ddmmyyyy, before_ddmmyyyy])
    if ok != "ok":
        print(f"  apply_date_range -> {ok}", flush=True)
        return False
    deadline = _t.time() + timeout
    while _t.time() < deadline:
        _t.sleep(1.0)
        txt = page.evaluate("() => document.body.innerText") or ""
        if "Delete results" in txt or re.search(
                r"\d{1,2} \w+ (?:19|20)\d{2} . \d{1,2} \w+ (?:19|20)\d{2}", txt):
