def audit_two_tier(known_models: dict, board: dict) -> dict:
    """Task D audit. Returns counts; also asserts the hard invariants.

    Does not mutate the cache -- main() calls this after writing so it reports
    on what is actually on disk.
    """
    frontier = board_frontier(board)
    margin = TIER2_MARGIN
    tiers = {"official": [], "unofficial": [], "unscored_not_on_board": [],
             "unscored_nothing_found": [], "unscored_non_coding": []}
    violations = {"above_frontier": [], "non_coding_scored": [],
                  "unofficial_labelled_official": [], "self_test_in_benchmark": []}
    for mid, m in (known_models or {}).items():
        if not isinstance(m, dict):
            continue
        # Self-test leakage is checked FIRST and independently of the tier walk:
        # a self-test number in a benchmark field makes effective_deepswe() None
        # (it is not search-sourced), so a check placed after the score test
        # could never fire -- the entry would be filed as merely unscored and
        # the 88.6 self-test values would pass the audit.
        if m.get("self_test_score") is not None:
            hit = [f for f in BENCHMARK_FIELDS
                   if _num(m.get(f)) is not None
                   and _num(m.get(f)) == _num(m.get("self_test_score"))
                   and m.get("score_source") in ("self-test",
                                                  "self-test-unreachable")]
            if hit:
                violations["self_test_in_benchmark"].append((mid, sorted(hit)))
        if classify_model_class(m) == "non-coding":
            if effective_deepswe(m) is not None:
                violations["non_coding_scored"].append(mid)
            else:
                tiers["unscored_non_coding"].append(mid)
            continue
        score = effective_deepswe(m)
        tier = str(m.get("score_tier") or "").strip().lower()
        if score is None:
            if (m.get("search_status") == "ok" and not m.get("score_found")):
                tiers["unscored_nothing_found"].append(mid)
            else:
                tiers["unscored_not_on_board"].append(mid)
            continue
        if tier == "official":
            tiers["official"].append(mid)
            if frontier is not None and score > frontier:
                violations["above_frontier"].append((mid, score))
        elif tier == "unofficial":
            tiers["unofficial"].append(mid)
            if frontier is not None and score > frontier + margin:
                violations["above_frontier"].append((mid, score))
            if m.get("score_source") in ("deepswe-board", "curated"):
                violations["unofficial_labelled_official"].append(mid)
        else:
            # A benchmark number with NO tier is exactly the pre-BRIEF10 state
            # that produced 13 fabricated scores. It is not trusted.
            tiers["unscored_not_on_board"].append(mid)
    return {"frontier": frontier, "margin": margin, "counts": {
        k: len(v) for k, v in tiers.items()},
        "members": {k: sorted(v) for k, v in tiers.items()},
        "violations": {k: v for k, v in violations.items() if v},
        "board_version": (board or {}).get("version"),
        "board_source_url": (board or {}).get("source_url"),
        "board_generated_at": (board or {}).get("generated_at"),
    }

