def _invalid_posting_reason(job) -> str:
    """Why this discovery result is not a job posting, or '' if it might be.

    Checked before any LLM, resume or navigation work, because discovery hands
    over things that are not postings and each one costs minutes:

      * raw API endpoints - a live run applied to
        https://boards-api.greenhouse.io/v1/boards/xai/jobs, extracted the
        hostname as the title, then burned 19+ LLM navigation steps hunting
        for an Apply button on a JSON response;
      * error URLs (?error=true) left behind by a failed redirect;
      * ATS error templates ("This page seems to have vanished").

    Deliberately narrow: a real posting URL is never an *-api.* host, never
    carries /v1/ or /v2/ paths, and never has its hostname as its title.
    """
    url = (job.get('url') or '').strip()
    title = (job.get('title') or '').strip()
    if _dead_posting_title(title):
        return f'ATS error page title: {title[:80]}'
    if not url:
        return ''
    u = url.lower()
    try:
        parts = urlparse(u)
        host = (parts.netloc or '').lower()
        path = (parts.path or '').lower()
    except Exception:
        host, path = '', ''
    if 'error=true' in u:
        return 'URL carries an error flag (?error=true)'
    if '-api.' in host or host.startswith('api.'):
        return f'API endpoint host: {host}'
    if path.startswith('/v1/') or path.startswith('/v2/'):
        return f'API path, not a posting: {path[:60]}'
    if title and host and title.lower().rstrip('/') == host.replace('www.', ''):
        return f'title is just the hostname ({host})'
    return ''


