    OTP field burns an authentication attempt.

    Returns the LAST match, because the newest message is the one that
    carries the code we are waiting for.
    """
    if not text:
        return None
    haystack = text
    lowered = haystack.lower()

    # 1. Keyword immediately followed by the digits — the strongest signal.
    for keywords, gap in ((_STRONG_CODE_KEYWORDS, r'[:\s#-]*'),):
        for kw in keywords:
            for m in re.finditer(re.escape(kw) + gap + r'([0-9]{4,8})', lowered):
                if _digits_are_plausible_code(m.group(1)):
                    return m.group(1)

    # 2. Digits sitting within a short window after a code keyword
    #    ("Your verification code is 481920", "code — 481920").
    best = None
    for kw in _STRONG_CODE_KEYWORDS + _WEAK_CODE_KEYWORDS:
        for m in re.finditer(re.escape(kw), lowered):
            window = lowered[m.end():m.end() + _CODE_WINDOW]
            for d in re.findall(r'\b([0-9]{4,8})\b', window):
                if _digits_are_plausible_code(d):
                    best = d if best is None else best
    if best:
        return best

    # 3. A standalone number is only accepted when the surrounding text proves
    #    it belongs to a verification message for THIS address.
    if email_filter:
        needle = email_filter.strip().lower()
        if needle and needle in lowered:
            for m in re.finditer(r'\b([0-9]{6})\b', haystack):
                if not _digits_are_plausible_code(m.group(1)):
                    continue
                window = lowered[max(0, m.start() - _CODE_WINDOW):m.end() + _CODE_WINDOW]
                if any(k in window for k in _STRONG_CODE_KEYWORDS):
                    return m.group(1)
    return None


async def fetch_code_from_mail_tab(context, email_filter: str = '') -> Optional[str]:
    """Scan open browser tabs for Gmail / Zoho / webmail to grab the latest verification code."""
    try:
        if not context:
            return None
        for p in context.pages:
            if p.is_closed():
                continue
            url = (p.url or '').lower()
            if any(h in url for h in ('mail.google.com', 'mail.zoho', 'outlook.live.com', 'webmail')):
                print(f"  [MAIL-GUARD] Found open webmail tab: {p.url[:60]}")
                text = await p.evaluate("() => document.body ? document.body.innerText : ''")
                code = extract_code_from_mail_text(text, email_filter)
                if code:
                    print(f"  [MAIL-GUARD] Extracted verification code from webmail tab: {code}")
                    return code
                print("  [MAIL-GUARD] No keyword-anchored verification code found in webmail tab.")
    except Exception as e:
        print(f"  [MAIL-GUARD] Error scanning mail tabs: {e}")
    return None

