const { spawn } = require('child_process');
const fs = require('fs');
const path = require('path');
const os = require('os');
const { isStructuredCouncilPrompt } = require('./prompt-wrap');

const AUTH_FAILURE = /authentication required|authentication failed|please visit the url to log in|error: authentication/i;

// An unauthenticated `agy` turn blocks for 60s before it gives up, and the seat is
// called in every phase (analysis, critique, review, integration, audit). Paying
// that 60s repeatedly would burn the whole discussion deadline, so the auth state
// is cached: within the TTL the seat fails fast without spawning, and a single
// successful turn flips it back to ok so a completed login is noticed.
const DEFAULT_AUTH_TTL_MS = 10 * 60 * 1000;
const DEFAULT_AUTH_STATE_PATH = path.join(os.homedir(), '.cache', 'mcp-council', 'agy-auth.json');

function readAuthState(file) {
  try {
    return JSON.parse(fs.readFileSync(file, 'utf-8'));
  } catch (err) {
    return null;
  }
}

function writeAuthState(file, state) {
  try {
    fs.mkdirSync(path.dirname(file), { recursive: true });
    fs.writeFileSync(file, JSON.stringify(state), 'utf-8');
  } catch (err) {
    // A read-only home must not break the council; the cache is an optimization.
  }
}

class AntigravityClient {
  constructor(options = {}) {
    this.binPath = options.binPath || '/home/ras/.local/bin/agy';
    this.timeoutMs = options.timeoutMs || 120000;
    this.model = options.model || process.env.AGY_MODEL || null;
    this.effort = options.effort || process.env.AGY_EFFORT || null;
    this.spawn = typeof options.spawn === 'function' ? options.spawn : defaultSpawn;
    this.authStatePath = options.authStatePath || process.env.AGY_AUTH_STATE || DEFAULT_AUTH_STATE_PATH;
    this.authTtlMs = Number.isFinite(options.authTtlMs) ? options.authTtlMs : DEFAULT_AUTH_TTL_MS;
    this.now = typeof options.now === 'function' ? options.now : Date.now;
  }

  /** 'ok' | 'unauthenticated' | 'unknown' for the current cache entry. */
  authStatus() {
    const cache = readAuthState(this.authStatePath);
    if (!cache || !cache.state || !Number.isFinite(cache.checkedAt)) return 'unknown';
    if (this.now() - cache.checkedAt > this.authTtlMs) return 'unknown';
    return cache.state === 'ok' ? 'ok' : 'unauthenticated';
  }

  _recordAuth(state) {
    writeAuthState(this.authStatePath, { state, checkedAt: this.now() });
  }

